/* 36 aulas provenientes dos resumos ampliados ENCCEJA MEC/Inep (2006), sem modificar o texto-base. */
(function(){'use strict';const lessons=[{"area":"Humanas","num":1,"title":"Cultura, memória e identidade","body":"Panorama do capítulo\n Identidades individuais e coletivas são construídas por experiências, lembranças e práticas culturais.\n\n Conceitos essenciais\n • Cultura inclui modos de viver e interpretar o mundo.\n\n • a memória seleciona e atribui sentidos ao passado.\n\n • identidades se transformam com as relações sociais e históricas.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Muitos outros elementos da nossa história individual poderiam ser considerados: as atividades\n    profissionais que exercemos, as festas, músicas e formas de lazer de que gostamos. Enfim, essas\n    preferências constituem a nossa identidade pessoal, mas estão diretamente relacionadas com a\n    história da sociedade em que vivemos. Imagine que você tivesse nascido no século XVIII em\n    Pernambuco. Certamente você não seria um trabalhador da indústria, nem consertaria carros, nem\n    gravaria discos. Poderia ser um cantor lírico,\n\n Texto-base 2 | página 3 do PDF do capítulo\n\n    Isso não significa dizer que todo o brasileiro seja da mesma forma, mas que reconhecemos que a\n    identidade social do brasileiro se afirma através dos vários hábitos e costumes semelhantes. Mesmo\n    que eu não goste de futebol, o Brasil continuará a ser reconhecido como o país do futebol.\n\n Texto-base 3 | página 6 do PDF do capítulo\n\n    Por fim, é importante lembrar que toda sociedade tem uma cultura. Os seres humanos da pré-\n    história produziam seus instrumentos de trabalho, faziam pinturas em paredes de cavernas, tinham\n    um modo de se vestir e criavam regras para a divisão do trabalho e organização da vida social. O\n    mesmo ocorria com os seres humanos que viveram em outros períodos históricos e também conosco,\n    que vivemos no Brasil do século XXI. Estando sempre ligados à história passada e presente,\n    constituímos nossa identidade individual e social que se reafirma a todo tempo através da cultura.\n    Não se esqueça:\n\n Texto-base 4 | página 7 do PDF do capítulo\n\n    Quem escolhia (o lugar onde a pessoa ia trabalhar, ao sair do depósito) era o Coronel Frederico.\n    Quando chegavam as famílias do interior, no dia de sair do depósito, ele botava um sofá assim em\n    frente da casa grande e sentava. Aí, aqueles agentes, aqueles empregados mandavam a gente ficar\n\n    assim, de fora numa fila, e ele ia chamando família por família... O exame que ele fazia era “cada um\n    apresente a mão!” Ele passava a mão assim, olhava: “esse aqui ta bom pra tal serviço...\n\n Texto-base 5 | página 8 do PDF do capítulo\n\n    A história de uma comunidade, seus prédios, ruas, avenidas e tradições também retratam a memória\n    e a identidade de um grupo. Os prédios antigos, as igrejas, as festas populares não são somente\n    resquícios do passado, mas a memória viva do que os habitantes daquela comunidade são hoje. As\n    tradições locais servem como referência para todos aqueles que ali nascem e crescem, são os laços e\n    a identidade que se estabelecem entre as pessoas.\n\n Texto-base 6 | página 10 do PDF do capítulo\n\n    Das fontes que você escolheu acima para realizar a pesquisa sobre a organização do trabalho no\n    século XX, quais são escritas? Se você escolheu o artigo de jornal, o manifesto camponês e a letra da\n    música, você acertou, pois se trata de registros escritos, através dos quais podemos compreender\n    algo a respeito da forma como os homens trabalhavam naquele período histórico. O depoimento do\n    trabalhador da fábrica de tecidos, que estudamos no item anterior, por sua vez, é o registro de um\n    depoimento oral, que é um outro tipo de fonte histórica.\n\n Texto-base 7 | página 12 do PDF do capítulo\n\n    Quando estudamos o sentido da memória para as pessoas e para as sociedades, afirmamos que\n    todos nós registramos as nossas alegrias, tristezas, momentos de mudança e outros eventos que\n    consideramos significativos. Alguns objetos são representativos dessas memórias. Guardamos uma\n    fotografia de uma pessoa querida ou de um dia marcante. Um objeto, um ingresso ou uma\n\n Texto-base 8 | página 14 do PDF do capítulo\n\n    mobilizou para impedir que a Serra fosse destruída, descaracterizando a cidade. Assim, a\n    conservação desse patrimônio foi um desejo dos moradores de ter não apenas o meio ambiente, mas\n    também a sua memória preservada.\n\n Síntese para fixação\n • Cultura inclui modos de viver e interpretar o mundo.\n\n • a memória seleciona e atribui sentidos ao passado.\n\n • identidades se transformam com as relações sociais e históricas."},{"area":"Humanas","num":2,"title":"A construção do território","body":"Panorama do capítulo\n Territórios são produzidos historicamente por relações de poder, ocupação e circulação.\n\n Conceitos essenciais\n • Fronteiras e divisões espaciais não são apenas naturais.\n\n • conflitos e interesses influenciam a organização territorial.\n\n • mapas expressam escolhas de representação do espaço.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 3 do PDF do capítulo\n\n    Para evitar que as favelas ganhem território, estão sendo instalados delimitadores. Um muro de\n    concreto está conseguindo evitar o encontro da Favela da Rocinha com as casas legalizadas, graças à\n    fiscalização permanente dos moradores do Alto da Gávea. A Rocinha ganhou ainda cercas (feitas de\n    trilhos interligados por cabos de aço). — Os delimitadores têm surtido efeito. Eles servem de\n    obstáculo à expansão da Rocinha para as laterais — argumenta um funcionário da Prefeitura do Rio\n    de Janeiro.\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    A Muralha da China se encontra na China, é claro, e tem aproximadamente 6.000 quilômetros de\n    extensão. A maior parte dela foi construída 300 anos antes do nascimento de Cristo, quando a China\n    se encontrava em guerra com a Mongólia. A função do muro era de defesa, ou seja, tinha como\n    objetivo evitar que os guerreiros da Mongólia invadissem o território chinês. Observe na foto que os\n    muros eram muito altos e a cada 100 metros, aproximadamente, existiam torres de vigilância, onde\n    ficavam soldados chineses vigiando a possível chegada de inimigos.\n\n Texto-base 3 | página 8 do PDF do capítulo\n\n    Observe que, na década de 1950, os principais fluxos eram de nordestinos em direção à região\n    Sudeste. Na década de 1960, continua o fluxo da década anterior, mas também surgem dois novos\n    fluxos: o primeiro, de nordestinos em direção à Amazônia; o segundo, de moradores da região Sul em\n    direção à região Centro-Oeste, em busca de novas terras para a produção agrícola. Na década de\n    1970, a saída de migrantes do Sul para as regiões Centro-Oeste e Norte se torna mais forte ainda.\n\n Texto-base 4 | página 9 do PDF do capítulo\n\n    A água, como qualquer outro recurso, é motivo para relações de poder ou de conflitos. O controle\n    e/ou a posse da água são sobretudo de natureza política, pois interessam a uma coletividade.\n\n Texto-base 5 | página 11 do PDF do capítulo\n\n    Depoimento 2 “Sempre lutei muito. Minha família veio pra cidade porque fui despedido quando as\n    máquinas chegaram lá na Usina. Seu moço, acontece que eu sou um homem da terra. Olho pro céu,\n    sei quando é tempo de plantar e de colher. Na cidade não fico mais. Eu quero um pedaço de terra,\n    custe o que custar. Hoje eu sei que não estou sozinho. Aprendi que a terra tem um valor social. Ela é\n\n    feita para produzir alimento. O que o homem come vem da terra. O que é duro é ver que aqueles que\n    possuem muita terra e não dependem dela para sobreviver, pouco se preocupam em produzir nela.”\n    – integrante do Movimento dos Trabalhadores Rurais Sem Terra (MST), de Corumbá – MS.\n\n Texto-base 6 | página 14 do PDF do capítulo\n\n    d) Vou contar para vocês um caso que sucedeu na Paraíba do Norte com um homem que se chamava\n    Pedro João Boa-Morte, lavrador de Chapadinha: talvez tenha morte boa porque vida ele não tinha.\n\n Texto-base 7 | página 18 do PDF do capítulo\n\n    Em mais uma ação protecionista, os Estados Unidos impuseram tarifas de 43,34% a produtos de aço\n    laminados a frio do Brasil. A medida prevê sobretaxas de 1,97% a 153,6% a produtos de outros 19\n    países fornecedores. As tarifas mais pesadas foram aplicadas às exportações da Índia (153,65%),\n    Rússia (137,33%), China (129,85%) e Japão (entre 112,56 % e 115,2%).\n\n Texto-base 8 | página 20 do PDF do capítulo\n\n    4 Podemos observar, no perfil da região, que a Cisjordânia é uma região elevada, o que favorece a\n    defesa militar, e possui uma vertente para o rio Jordão. Ora, se a água é um recurso escasso naquela\n    região, ela é um recurso estratégico, muito importante. Logo, a alternativa correta corresponde à\n    letra “e”. Por que as demais opções estão erradas? Porque a região da Cisjordânia não é de planície\n    (letra “a”), não abrange as duas margens do rio Jordão (letra “b”), não é ocupada em sua maioria por\n    israelenses (letra “c”) e não faz fronteira com o mar Mediterrâneo (letra “d”).\n\n Síntese para fixação\n • Fronteiras e divisões espaciais não são apenas naturais.\n\n • conflitos e interesses influenciam a organização territorial.\n\n • mapas expressam escolhas de representação do espaço."},{"area":"Humanas","num":3,"title":"O que estamos fazendo com a natureza?","body":"Panorama do capítulo\n As sociedades modificam paisagens e recursos naturais ao produzir e ocupar espaços.\n\n Conceitos essenciais\n • Atividades econômicas geram impactos ambientais.\n\n • diferentes grupos utilizam e valorizam a natureza de maneiras diversas.\n\n • escolhas de desenvolvimento envolvem conflitos e limites ecológicos.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Se quisermos sobreviver enquanto espécie, precisamos aproveitar os conhecimentos acumulados\n    sobre o planeta para abandonarmos a posição de passivos passageiros e nos transformarmos em\n    ativos tripulantes, capazes de organizar internamente nossa nave para que ela tenha rumo e sentido.\n\n Texto-base 2 | página 3 do PDF do capítulo\n\n    Herdamos de nossos ancestrais a habilidade de fazer ferramentas e de produzir fogo, bem como a\n    competência de transmitir esses conhecimentos por meio de diferentes linguagens. Acumulamos\n    conhecimentos sobre os processos naturais que nos possibilitaram aumentar os espaços ocupados,\n\n Texto-base 3 | página 6 do PDF do capítulo\n\n    • o espaço ocupado por essa atividade é enorme, e poderia ser melhor utilizado para a prática da\n    agricultura ou para a preservação das formações vegetais originais, que não seriam destruídas para\n    a formação de novos pastos;\n\n Texto-base 4 | página 7 do PDF do capítulo\n\n    fazem a água retornar à superfície purificada. Uma parte é novamente transformada em vapor, outra\n    escorre e outra se infiltra no solo, formando depósitos de água subterrânea. É o ciclo da água.\n\n Texto-base 5 | página 10 do PDF do capítulo\n\n    Levando em conta o seu conhecimento sobre as questões relativas à água, responda: 1. Quais seriam\n    as suas propostas no sentido de resolver os problemas relativos à utilização da água no planeta?\n    Considere todos os elementos possíveis, como o consumo por setor, o tempo de reposição, a\n    distribuição geográfica da oferta e do consumo de água, a poluição etc..\n\n Texto-base 6 | página 14 do PDF do capítulo\n\n    Acompanhe o raciocínio. Se a população mundial nos próximos 50 anos aumentar em 3,2 bilhões de\n    habitantes, como se espera, seria necessário produzir mais 960 milhões de toneladas de grãos, para\n    manter a média de consumo atual (3,2 bilhões X 0,3 ton). Com as técnicas atualmente utilizadas, isso\n    representaria um aumento de 960 bilhões de toneladas no déficit hídrico já existente no mundo, que\n    é de 160 bilhões. Onde conseguir essa água?\n\n Texto-base 7 | página 16 do PDF do capítulo\n\n    A maioria dos problemas que enfrentamos hoje no planeta são conseqüências das formas que a\n    espécie humana desenvolveu para produzir e consumir os bens que existem atualmente.\n\n Texto-base 8 | página 18 do PDF do capítulo\n\n    Existem soluções técnicas para todos os problemas apresentados. Mas todas elas implicam algum\n    tipo de “prejuízo” , isto é, vão custar mais trabalho, podem causar outros tipos de problema\n    ambiental, os lucros podem diminuir ou uma parcela da humanidade deverá reduzir a quantidade de\n    produtos que consome.\n\n Síntese para fixação\n • Atividades econômicas geram impactos ambientais.\n\n • diferentes grupos utilizam e valorizam a natureza de maneiras diversas.\n\n • escolhas de desenvolvimento envolvem conflitos e limites ecológicos."},{"area":"Humanas","num":4,"title":"Estado e direito","body":"Panorama do capítulo\n Instituições políticas e normas regulam relações sociais e disputas de interesses.\n\n Conceitos essenciais\n • O Estado exerce funções de organização e poder.\n\n • direitos são construídos e disputados historicamente.\n\n • leis e instituições devem ser analisadas em seu contexto social.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Logo que Amulius, o rei usurpador, ficou sabendo disso, mandou trancafiar Silvia numa prisão e\n    ordenou que os gêmeos fossem colocados numa cesta e jogados no rio Tibre, para que a corrente os\n    levasse para bem longe dali. Como os gêmeos eram filhos de um deus, nem mesmo um sujeito sem\n    escrúpulos como Amulius tinha coragem de matá-los.\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    b) seja entre determinados países que guerreiam por questões territoriais, econômicas, religiosas\n    etc. (e aqui podemos lembrar das guerras entre os israelenses e os palestinos, ou entre os\n    paquistaneses e os indianos).\n\n Texto-base 3 | página 5 do PDF do capítulo\n\n    Rômulo, ao fundar a cidade de Roma, logo ordenou que fosse levantado um muro que deveria cercar\n    e proteger os romanos dos seus inimigos externos. Dentro desse espaço cercado pelos muros,\n    vigorariam leis que deveriam proteger os romanos, punindo aqueles que não as respeitassem,\n    fossem eles cidadãos ou não (como era o caso dos estrangeiros e dos escravos).\n\n Texto-base 4 | página 14 do PDF do capítulo\n\n    O Direito é, portanto, um ordenamento (uma organização posta em prática através de leis) que,\n    ainda que seja estabelecido a partir de um consenso social, só se realiza através da força e em\n    defesa de determinados princípios que podem:\n\n Texto-base 5 | página 15 do PDF do capítulo\n\n    Thomas Hobbes imaginava que, diante deste quadro de guerra de todos contra todos, os indivíduos\n    isolados e os grupos mais fracos uniriam suas forças e os seus bens para se\n\n Texto-base 6 | página 17 do PDF do capítulo\n\n    Mas conforme Roma passou a conquistar outras terras, a fundar colônias e a ter domínio sobre outros\n    territórios, os romanos viram-se obrigados a preocupar-se também com as relações que se\n    estabeleciam entre pessoas de cidades diferentes.\n\n Texto-base 7 | página 19 do PDF do capítulo\n\n    A exploração do trabalho de estrangeiros, ou de pessoas oriundas das regiões pobres do Brasil\n    (alternativa “c”), não chega sequer a constituir uma solução, pois não faz mais do que transferir o\n    problema para uma outra região, ou para uma outra parcela da população.\n\n Texto-base 8 | página 22 do PDF do capítulo\n\n    Neste conflito, três religiões diferentes (judaica, cristã e muçulmana), que tiveram sua origem\n    naquela região, reivindicam a importância fundamental do território em disputa, e particularmente\n    da cidade de Jerusalém, para as suas respectivas culturas.\n\n Síntese para fixação\n • O Estado exerce funções de organização e poder.\n\n • direitos são construídos e disputados historicamente.\n\n • leis e instituições devem ser analisadas em seu contexto social."},{"area":"Humanas","num":5,"title":"Cidadania","body":"Panorama do capítulo\n Cidadania envolve direitos, deveres e participação na vida pública.\n\n Conceitos essenciais\n • Direitos civis, políticos e sociais têm trajetórias históricas.\n\n • democracia depende da participação e do respeito à pluralidade.\n\n • exclusões sociais limitam o exercício efetivo dos direitos.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Para começar a pensar, eu posso tomar a Constituição Brasileira, que vale acima de qualquer outra\n    lei. A nossa atual constituição (1988) estabelece, no seu artigo primeiro, que um dos fundamentos da\n    República Brasileira é a cidadania. Assim, nossa mais importante lei, a Constituição Brasileira, dá um\n    destaque\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    Na maioria dos movimentos sociais ocorridos depois dos gregos, ficava a mesma dúvida de\n    Aristóteles: afinal, quem é cidadão? Quem tem direitos? Quem deve fazer as leis? Quem tem\n\n Texto-base 3 | página 5 do PDF do capítulo\n\n    A luta contra o rei absoluto continuou na Europa. No século XVIII (1701 a 1800), o rei da França\n    perdeu seus poderes e, tal como o rei da Inglaterra, foi executado. Mais uma vez acontece o que já\n    vimos na Inglaterra: os burgueses assumem o poder, com grandes movimentos de revolta dos mais\n    pobres. Os trabalhadores do campo da França, por exemplo, não queriam apenas derrubar um rei,\n    queriam a terra também! Os pobres das cidades não queriam apenas derrubar o absolutismo,\n    queriam também mais chances de emprego, melhores moradias, menos impostos e mais justiça! Os\n    miseráveis da Inglaterra queriam uma revolução muito mais forte do que a que estava acontecendo\n    na França.\n\n Texto-base 4 | página 7 do PDF do capítulo\n\n    Agora que você já aprendeu mais, vamos fazer uma atividade? Tendo lido com atenção o texto\n    anterior, assinale qual a alternativa correta. Essa atividade precisa de um pouco mais de esforço do\n    que a primeira. a) A burguesia na Inglaterra e na França uniu-se para apoiar o Absolutismo. b) A\n    burguesia inglesa e a francesa defenderam o voto dos pobres como base da cidadania. c) Os\n    trabalhadores viraram aliados dos reis absolutos contra a burguesia da Inglaterra e França. d) Para a\n    burguesia da Inglaterra e da França o direito à cidadania estava ligado ao dinheiro. e) Os socialistas\n    combatiam o voto universal defendido pelos burgueses da Inglaterra e\n\n Texto-base 5 | página 9 do PDF do capítulo\n\n    O que foi ocorrendo no século XX é que muitos perceberam que o direito à cidadania não era apenas\n    o direito de voto, mas também o direito a um salário justo e a direitos básicos. O conceito de\n\n     cidadania foi sendo ampliado no século XX para incluir o conceito de bem estar social, de dignidade\n     no trabalho, de uma aposentadoria justa após uma vida de trabalho.\n\n Texto-base 6 | página 11 do PDF do capítulo\n\n     Veja um exemplo. O governo queria divulgar notícias boas. Por exemplo, o governo queria que\n     falassem bastante que o Brasil foi tricampeão mundial de futebol no México em 1970. Isso podia\n     publicar. No entanto, ninguém podia falar que a proporção de pobres estava aumentando e os ricos\n     estavam ficando mais ricos no mesmo período. Isso não podia publicar. Também não podia ser\n     publicada nenhuma crítica aos gastos do governos em grandes obras, como a ponte Rio-Niterói ou a\n     Usina Hidrelétrica de Itaipu. Nada podia ser criticado. Dessa forma, a censura colaborava para limitar\n     a cidadania brasileira no período, como você pode ver no desenho seguinte.\n\n Texto-base 7 | página 13 do PDF do capítulo\n\n     § 1° É enganosa qualquer modalidade de informação ou comunicação de caráter publicitário, inteira\n     ou parcialmente falsa, ou, por qualquer outro modo, mesmo por omissão, capaz de induzir ao erro o\n     consumidor a respeito da natureza, características, qualidade, quantidade, propriedades, origem,\n     preço e quaisquer outros dados sobre produtos e serviços.\n\n Texto-base 8 | página 15 do PDF do capítulo\n\n     Seria incompleto falar de cidadania sem indicar duas coisas importantes. A primeira, você deve ter\n     concluído ao longo do texto. A cidadania não é um presente oferecido a você de graça. A cidadania é\n     construída por nós. Só existe um responsável direto pelos seus direitos: você. Assim, dificilmente\n     obtém alguma coisa quem fica sentado esperando que o mundo venha dar os seus direitos de forma\n     fácil. As transformações nos conceitos de cidadania ocorreram porque as pessoas lutaram. Como\n     você viu, se as mulheres não tivessem se organizado e defendido seu direito de cidadãs e seu direito\n     a votar, talvez até hoje as eleições só fossem para os homens. Assim, cidadania é construída pelos\n     interessados, como eu e você.\n\n Síntese para fixação\n • Direitos civis, políticos e sociais têm trajetórias históricas.\n\n • democracia depende da participação e do respeito à pluralidade.\n\n • exclusões sociais limitam o exercício efetivo dos direitos."},{"area":"Humanas","num":6,"title":"A vida cotidiana e os impactos ambientais","body":"Panorama do capítulo\n Há relações entre hábitos diários, consumo, infraestrutura e problemas ambientais.\n\n Conceitos essenciais\n • Produção e descarte de resíduos afetam o espaço.\n\n • uso de água e energia envolve decisões individuais e coletivas.\n\n • políticas públicas são relevantes para reduzir impactos.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    No Brasil, a maior parte da população vive em cidades. Isso também se verifica na maioria dos\n    demais países da América do Sul, na Europa, na América do Norte e no Japão. Porém, no mundo todo,\n    a população rural ainda supera a urbana, graças a países como a China, a Índia e a maioria dos\n    países africanos. Observe o mapa 1, na página a seguir:\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    As multas para os crimes ambientais serão calculadas, a partir de hoje, pelo total da área devastada,\n    árvores derrubadas ou animais mortos. Os recursos arrecadados com a punição serão investidos na\n    fiscalização. Segundo o decreto, a pessoa ou a empresa que poluir o ambiente a ponto de matar\n    animais, causar danos à saúde humana e tornar áreas impróprias para a ocupação receberá multas\n    que vão de R$ 1.000 a R$ 50 milhões. Antes da regulamentação, a multa máxima para um crime\n    ambiental era de R$ 4.900. Também serão aplicadas multas para crimes contra a fauna (caçar, matar\n    e prender animais sem licença), a flora (cortar e depredar árvores, soltar balões) e o patrimônio\n    cultural. A multa mínima é de R$ 50. Além das multas, a legislação atual já previa pena de prisão de\n    até seis anos para esse tipo de infração.\n\n Texto-base 3 | página 6 do PDF do capítulo\n\n    Se destinar corretamente os resíduos sólidos é difícil, tratar o esgoto não é mais simples. Os dejetos\n    humanos devem ser transportados e tratados antes de serem depositados em alguma área. Para\n    diminuir as toxinas contidas no esgoto, são usados sofisticados processos técnicos, que não são\n    baratos. No Brasil, menos de 5% do total do esgoto coletado é tratado, enquanto que, em países\n    ricos, o índice está em torno de 70%.\n\n Texto-base 4 | página 9 do PDF do capítulo\n\n    Em países e regiões de capital intensivo, ou seja, áreas em que os investimentos na produção\n    ocorrem em níveis elevados, encontram-se máquinas agrícolas, animais confinados, sementes\n    selecionadas, defensivos agrícolas, técnicos especialistas em solos e no cultivo de determinados\n    produtos agrícolas, sofisticados sistemas de irrigação, silos para armazenar a colheita e uma\n    infra-estrutura viária capaz de escoar a produção. Em geral, essa produção é suficiente para atender\n    o mercado interno e para a exportação.\n\n Texto-base 5 | página 11 do PDF do capítulo\n\n    tipo climático que predomina em nosso país, onde ocorrem, na maior parte do território, chuvas\n    fortes ao longo do ano ou em parte dele. A proibição gerou vantagem comercial. Países europeus,\n    acostumados a consumir produtos de soja, preferem comprar soja natural a transgênica, como a\n    cultivada na Argentina e nos Estados Unidos. Por isso, agricultores brasileiros conseguiram ampliar a\n    participação no comércio internacional de soja, levando o país à segunda posição entre os produtores\n    do mundo.\n\n Texto-base 6 | página 14 do PDF do capítulo\n\n    A adoção desse modelo de geração de energia é condizente com algumas características do país,\n    que possui extensos corpos d’água, clima tropical que recebe chuvas torrenciais em grande parte do\n\n Texto-base 7 | página 17 do PDF do capítulo\n\n    A energia nuclear decorre do rompimento do núcleo de um átomo de urânio, que precisa ser\n    processado antes de ser empregado como combustível em uma usina nuclear. Esse modelo de\n    geração é muito criticado, pois dele resulta o lixo nuclear, material que sobra do processamento do\n    urânio e peças que têm contato com a radiação nuclear. O contágio com radiação nuclear pode ser\n    fatal para os seres humanos.\n\n Texto-base 8 | página 19 do PDF do capítulo\n\n    No Brasil, houve a criação do Ministério do Meio Ambiente, que atua em escala nacional por meio de\n    órgãos, como o IBAMA - Instituto Brasileiro de Meio Ambiente e Recursos Naturais -, entre outros. Mas\n    também surgiram órgãos de controle ambiental em escala estadual e, em alguns municípios,\n    conselhos ambientais e até secretarias municipais de meio-ambiente, como em São Paulo. Isso gerou\n    uma demanda por novos profissionais especialistas em temas ambientais.\n\n Síntese para fixação\n • Produção e descarte de resíduos afetam o espaço.\n\n • uso de água e energia envolve decisões individuais e coletivas.\n\n • políticas públicas são relevantes para reduzir impactos."},{"area":"Humanas","num":7,"title":"O mundo urbano e industrial","body":"Panorama do capítulo\n Industrialização e urbanização transformam trabalho, paisagem e relações sociais.\n\n Conceitos essenciais\n • Cidades concentram atividades e serviços.\n\n • expansão urbana pode gerar segregação e problemas de infraestrutura.\n\n • mudanças industriais reorganizam a produção e o cotidiano.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 3 do PDF do capítulo\n\n    Aliás, você já reparou como sua vida também está rodeada por máquinas e ferramentas de todos os\n    tipos, das mais simples às mais complicadas? Já percebeu como elas agitam, marcam e determinam\n    o ritmo de nossas vidas mesmo fora do ambiente do trabalho? Olhe nesse exato momento ao redor\n    de onde estiver e veja como é possível identificá-las imediatamente. Se você estiver dentro de casa,\n    provavelmente há por perto um rádio, TV, geladeira, fogão ou liquidificador. No trabalho, seja o\n    realizado no campo ou na cidade, é possível encontrar colhedeiras, serras, roçadeiras, tornos,\n    interfones, telefones e computadores. Nas ruas encontramos tratores, semáforos, carros, caminhões\n    e utilizamos ônibus, metrô e motos. E, quando olhamos para o céu, vemos aviões e helicópteros.\n\n Texto-base 2 | página 5 do PDF do capítulo\n\n    Originalmente as máquinas também procuram imitar os movimentos humanos (os robôs não são\n    imitação do homem?). Mas existem duas outras características mais importantes que as diferenciam:\n    elas são formadas por uma série de articulações e mecanismos, compostos por ferramentas,\n    dobradiças, pivôs e catracas; e usam a força da natureza (do vento, da água e do vapor) para criar e\n    manter os movimentos mecanicamente. Iniciado o movimento, a máquina o repete, por meio de\n    todas essa articulações e mecanismos, automaticamente, sem parar, enquanto tiver energia. E mais:\n    esses movimentos repetem mecanicamente a ação de vários homens ao mesmo tempo. Sem\n    precisar mais da ajuda humana, o trabalhador apenas dirige a máquina, que substitui assim o\n    trabalho humano.\n\n Texto-base 3 | página 8 do PDF do capítulo\n\n    Agora já podemos prosseguir com nossa conversa. Começávamos a falar do surgimento do trabalho\n    mecânico e automático realizado pelas máquinas. Quando se trata desse assunto, é preciso levar em\n    conta necessariamente as formas de energias utilizadas, pois, sem elas, as máquinas não se mantêm\n    em movimento. A força humana e a dos animais são limitadas para colocar em funcionamento\n    dezenas de máquinas durante muito tempo, assim como a água também cria uma série de\n    dificuldades. Já pensou como uma locomotiva movida a força hidráulica poderia se deslocar?\n    Impossível, não é?\n\n Texto-base 4 | página 10 do PDF do capítulo\n\n    a) Energia mecânica pela dos animais; da máquina pela ferramenta; da fábrica pela oficina\n    manufatureira; e da grande produção pela pequena produção local. b) Energia dos animais pela\n    mecânica; da ferramenta pela máquina; da oficina manufatureira pela fábrica; e da pequena\n    produção local pela grande produção. c) Energia mecânica pela dos animais; da ferramenta pela\n    máquina rudimentar; da oficina manufatureira pela fábrica; e da pequena produção local pela grande\n    produção. d) Energia física pela elétrica; da maquinofatura pela máquina; da oficina manufatureira\n    pela fábrica; e da produção continental pela produção global.\n\n Texto-base 5 | página 12 do PDF do capítulo\n\n    Curioso também é o fato de as imagens dos irmãos Lumière registrarem um dos grandes símbolos da\n    época, que representava grandiosidade, velocidade e força: a locomotiva. Porém, a locomotiva nada\n    mais era do que uma daquelas máquinas a vapor sobre as quais já falamos anteriormente.\n\n Texto-base 6 | página 14 do PDF do capítulo\n\n    O período que justamente começa nas duas últimas décadas do século XIX e vai até a Primeira\n    Guerra Mundial (1914-1918) foi marcado por novas transformações. Elas foram tão importantes que\n    marcaram o mundo contemporâneo e a vida das pessoas durante todo o século XX e, por isso, muitos\n    estudiosos denominam esse conjunto de Segunda Revolução Industrial. Mas, na verdade, as\n    mudanças ocorridas, a partir da década de 1870, não foram simples prolongamentos daquela\n    primeira Revolução Industrial. Já estudamos como as diferenças entre o trem e o cinema demonstram\n    muito bem as profundas mudanças, não é mesmo? Por isso, talvez fosse melhor chamá-la de uma\n    nova revolução científica e tecnológica, muito embora a idéia de uma Segunda Revolução Industrial\n    não seja má ou esteja errada.\n\n Texto-base 7 | página 15 do PDF do capítulo\n\n    SEVCENKO, Nicolau. O prelúdio republicano, astúcias da ordem e ilusões do progresso. In:______.\n    (Org.). História da vida privada no Brasil. São Paulo: Companhia das Letras, 1999. v.3, p.9-10.\n\n Texto-base 8 | página 18 do PDF do capítulo\n\n    Naquela época existiam sociedades – e ainda existem muitas delas – que partiam de outros princípios\n    e lógica de funcionamento, para as quais a tecnologia e as máquinas tinham outro sentido, grau de\n    importância ou nem existiam. Essas sociedades que no fim do século XIX não viviam de acordo com\n    esses princípios acabaram sendo dizimadas (como os indígenas nos Estados Unidos) ou\n    profundamente transformadas (como a Índia ou Japão). Mas nada disso ocorreu sem resistência ou\n    muita luta. Você já deve ter visto muitos filmes sobre a conquista do oeste norte- americano em que\n    os indígenas travaram verdadeiras guerras contra os colonizadores, mas sempre com visível\n    desvantagem (não conheciam a pólvora, não manipulavam fuzis e revólveres). Outras dezenas de\n    exemplos ocorreram na América, Ásia e África.\n\n Síntese para fixação\n • Cidades concentram atividades e serviços.\n\n • expansão urbana pode gerar segregação e problemas de infraestrutura.\n\n • mudanças industriais reorganizam a produção e o cotidiano."},{"area":"Humanas","num":8,"title":"O trabalhador, as tecnologias e a globalização","body":"Panorama do capítulo\n Mudanças tecnológicas e conexões globais reorganizam o trabalho e a economia.\n\n Conceitos essenciais\n • A circulação de produtos e informações amplia interdependências.\n\n • novas tecnologias modificam profissões.\n\n • os benefícios da globalização são distribuídos de forma desigual.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Observe também que o contato entre a empresa contratante e o candidato ao emprego modificou-se.\n    Enquanto, nos anos de 1970, o contato era realizado por meio de uma carta endereçada à redação\n    do jornal, na atualidade solicita-se envio de um e-mail para a redação do jornal.\n\n Texto-base 2 | página 5 do PDF do capítulo\n\n    Comparando com os dias atuais, a descrição feita pela autora em seu livro não passa de “coisa do\n    passado”. Na atualidade, os automóveis atingem velocidades incríveis, encurtando as distâncias e\n    agilizando o sistema de transportes. Porém, os riscos de acidentes resultantes da modernização das\n    máquinas, associados à imprudência de muitos motoristas, mudaram novamente a paisagem nas\n    rodovias e nas cidades. A tecnologia atual gerou condições para a popularização de uma nova forma\n    de controle de tráfego – os radares fotográficos. Os radares, conhecidos em algumas cidades por\n    “pardais”, foram incorporados para fiscalizar a velocidade, a ultrapassagem proibida e o avanço de\n    sinais fechados, multando os motoristas imprudentes e os que não respeitam as leis de trânsito\n    vigentes no país.\n\n Texto-base 3 | página 6 do PDF do capítulo\n\n    O resultado claro da aplicação desses princípios é a redução para o operário da necessidade de\n    pensar e a redução ao mínimo de seus movimentos. Sempre que possível, o operário faz apenas uma\n    coisa, com um só movimento.”(...) “O trabalho repetitivo, o fazer contínuo, sempre do mesmo modo,\n    de uma única coisa, é uma perspectiva terrível para certo tipo de mentalidade. É terrível também\n    para mim. Eu não conseguiria nunca fazer a mesma coisa todos os dias; mas, para outro tipo de\n    pessoa, diria talvez que a maioria das pessoas, as operações repetitivas não são motivo de terror. Na\n    realidade, para alguns tipos de mentalidade, pensar é verdadeiramente um castigo. Para essa gente,\n    o trabalho ideal é aquele em que o instinto criativo não se deve exprimir. Os trabalhos em que é\n    preciso colocar cérebro e músculos têm poucos apreciadores.... (...)\n\n Texto-base 4 | página 8 do PDF do capítulo\n\n    A robotização na produção automobilística iniciou-se pelo Japão, na década de 1970. A fábrica de\n    automóveis Toyota passou a produzir utilizando a automação industrial. Essa foi, sem dúvida, a\n    grande transformação ocorrida na organização do trabalho contemporâneo. Se a organização do\n    trabalho até então existente empregava muitos trabalhadores em funções de pouca qualificação, a\n\n    incorporação das novas tecnologias de automação no setor produtivo tem gerado uma diminuição\n    sistemática da mão-de- obra empregada. A isso denomina-se desemprego estrutural, que pode ser\n    compreendido como o emprego eliminado pela introdução de novas tecnologias no setor produtivo,\n    uma vez que a máquina executa uma função em menor tempo e\n\n Texto-base 5 | página 11 do PDF do capítulo\n\n    Assim como as novas tecnologias têm proporcionado grande alteração no interior das fábricas, o\n    campo também tem se modificado. Até a década de 1970, os países pobres utilizavam grande\n    quantidade de mão-de-obra agrícola, principalmente em períodos de colheita. Muitos desses\n    trabalhadores, conhecidos no Brasil por “bóias-frias”, passaram a morar nas cidades e a trabalhar no\n    campo. Com a mecanização acelerada do campo, conseqüência da tentativa de expandir a produção\n    destinada à exportação e à indústria, essa mão-de-obra passou a incorporar um contingente enorme\n    de desempregados nas áreas urbanas. Esse fato, associado à grande concentração de terras nas\n    mãos de poucos, possibilitou a formação de movimentos sociais organizados, como é o caso, no\n    Brasil, do MST – Movimento dos Sem Terra.\n\n Texto-base 6 | página 13 do PDF do capítulo\n\n    A polêmica sobre vantagens e desvantagens dos alimentos modificados geneticamente está longe do\n    fim, mas a Empresa Brasileira de Pesquisa Agropecuária (Embrapa) faz questão de conquistar essa\n    tecnologia. A estatal discute com a empresa Monsanto um contrato de licenciamento para produção\n    de soja transgênica resistente ao herbicida Roundup Ready.\n\n Texto-base 7 | página 15 do PDF do capítulo\n\n    De que modo as informações transmitidas imediatamente podem influenciar as nossas vidas? Como\n    a divulgação dessas informações altera os hábitos de consumo de uma população?\n\n Texto-base 8 | página 17 do PDF do capítulo\n\n    (...) O Ford Fiesta é montado em Valência (Espanha), mas os vidros vêm do Canadá; o carburador, da\n    Itália; o radiador, da Áustria; os cilindros, as baterias e a ignição, da Inglaterra; os pistões, da\n    Alemanha; e o eixo de transmissão, da França.(...) as roupas japonesas, consumidas no mercado\n    americano, são fabricadas em Hong Kong, Taiwan, Coréia do Sul e Cingapura; já a indústria de\n    confecção norte-americana, quando inscreve em seus produtos “made in USA”, se esquece de\n    mencionar que eles foram produzidos no México, no Caribe, ou nas Filipinas.”\n\n Síntese para fixação\n • A circulação de produtos e informações amplia interdependências.\n\n • novas tecnologias modificam profissões.\n\n • os benefícios da globalização são distribuídos de forma desigual."},{"area":"Humanas","num":9,"title":"Os homens, o tempo, o espaço","body":"Panorama do capítulo\n A compreensão histórica depende de situar experiências humanas no tempo e no espaço.\n\n Conceitos essenciais\n • Mudanças e permanências coexistem.\n\n • diferentes grupos vivenciam processos históricos de formas distintas.\n\n • fontes e registros permitem investigar interpretações do passado.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Em outras épocas, o tempo dedicado ao trabalho tinha por objetivo produzir os bens, como alimentos\n    e roupas, de que as pessoas necessitavam para sobreviver, sem que ninguém se precocupasse com\n    a quantidade de horas que eram necessárias para cumprir a tarefa de produzi-los.\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    ciência procura estudar como se deu a formação do planeta, de suas paisagens, das rochas, das\n    florestas, dos mares e oceanos, sem recorrer a textos sagrados. O tempo geológico situa a idade da\n    Terra em aproximadamente 4,5 bilhões de anos. Esse longo período de tempo foi dividido em eras\n    geológicas, cada qual marcando um diferente período na história da vida do planeta, identificado por\n    grandes transformações provocadas pelas forças da natureza. Quando pensamos na longa duração\n    do tempo geológico, podemos refletir como o ser humano ocupa apenas uma pequena parcela de sua\n    história.\n\n Texto-base 3 | página 7 do PDF do capítulo\n\n    Em muitas sociedades, o sol, a lua e as estrelas são vistos como seres vivos, como representações de\n    divindades, trazendo possíveis mensagens sobre o futuro ou simbolizando coisas acontecidas no\n    passado. Assim, o aparecimento da lua cheia, numa certa época do ano, pode ser visto como motivo\n    para se festejar um período especial para a comunidade, como o início das atividades de colheita ou\n    do plantio.\n\n Texto-base 4 | página 9 do PDF do capítulo\n\n    Todas as sociedades procuraram inventar meios e instrumentos para medir a passagem do tempo.\n    Os Tembé, como vimos, utilizam o relógio de sol; outros inventaram a ampulheta, medindo o tempo\n    pela areia que escorria; em Madagascar, um país da África, podia-se medir o tempo pelo “cozimento\n    do arroz”; em vários outros países, mede-se o tempo pela duração das rezas e orações; em regiões\n    do litoral, as horas são calculadas pelas marés. O que há em comum entre essas diferentes formas\n    de medir o tempo é a despreocupação em marcar a passagem do tempo com precisão matemática.\n\n Texto-base 5 | página 12 do PDF do capítulo\n\n    Os calendários são organizados pelo conhecimento astronômico, mas eles estão relacionados a\n    outras formas de controlar o tempo e as atividades dos homens. Por esta razão, as pessoas que criam\n\n    os calendários possuem poder. Afinal, a sociedade se organiza em função de calendários. Pelos\n    calendários, existem as festas de Natal, de Ano Novo, do carnaval etc. Com eles, a vida das pessoas\n    pode ser ordenada e controlada. No mundo ocidental, a Igreja Católica procurou estabelecer um\n    controle sobre o tempo, que era considerado como pertinente a Deus, organizando-o através dos\n    calendários. Com o cristianismo, o primeiro dia da semana passou a ser chamado de domingo, sendo\n    considerado como dia em que não se trabalhava e deveria ser consagrado a Deus. Assim, podemos\n    perceber que o poder dos calendários está também ligado à religião.\n\n Texto-base 6 | página 15 do PDF do capítulo\n\n    Vimos que há desacordo entre os historiadores em relação à divisão do tempo histórico em Pré-\n    História e História, como se isso pudesse valer para todos os povos da humanidade. Será que o\n    mesmo acontece em relação às divisões que os historiadores criaram para a História? Primeiro,\n    precisamos entender que divisão foi essa. Os historiadores europeus repartiram a História da\n    humanidade em quatro grandes períodos, escolhendo, como marcos históricos, grandes\n    acontecimentos políticos. Segundo essa divisão, a História é dividida em 4 períodos:\n\n Texto-base 7 | página 17 do PDF do capítulo\n\n    maior formando uma conjuntura, como o período das eleições municipais, e o início, desenvolvimento\n    e término de nova administração; e ainda existe o movimento estrutural, formado pelas lentas\n    mudanças na economia industrial do país e do mundo que acabam afetando a vida do município.\n\n Texto-base 8 | página 20 do PDF do capítulo\n\n    Os países possuem diferenças entre as horas do dia devido ao chamado fuso horário. Assim,\n    enquanto nós, brasileiros, assistíamos ao jogo do Brasil contra a China tomando café da manhã\n    (8h30), os franceses almoçavam (12h30), os\n\n Síntese para fixação\n • Mudanças e permanências coexistem.\n\n • diferentes grupos vivenciam processos históricos de formas distintas.\n\n • fontes e registros permitem investigar interpretações do passado."},{"area":"Natureza","num":1,"title":"A ciência como construção humana","body":"Panorama do capítulo\n A ciência é uma atividade histórica e coletiva, desenvolvida para explicar fenômenos e enfrentar\n problemas humanos.\n\n Conceitos essenciais\n • A observação e a elaboração de explicações transformam a vida cotidiana.\n\n • descobertas científicas dependem do contexto social e dos recursos disponíveis.\n\n • o uso do conhecimento pode produzir benefícios ou riscos.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 3 do PDF do capítulo\n\n    Imagine uma situação muito comum em sua vida, ou na vida de quase todas as pessoas. Imagine,\n    por exemplo, que, depois de um dia de trabalho, você finalmente chega a casa. É começo da noite.\n    Você faz coisas tão comuns e rotineiras como ligar a iluminação, lavar suas mãos, aquecer sua\n    refeição e, durante o jantar ou depois dele, ligar a televisão para assistir a seus programas favoritos.\n    Tudo isso é tão comum e tão fácil, tudo isso faz parte da vida das pessoas há tanto tempo que você\n    nem pensa no que está fazendo, que você nem se interroga sobre “como” e “por que” é possível\n    fazer tudo isso.\n\n Texto-base 2 | página 5 do PDF do capítulo\n\n    O conhecimento que a ciência produz não é a revelação de erros anteriores, não é a revelação de que\n    os homens que não o possuíam eram ignorantes ou, pior, desprovidos de inteligência. Esse\n    conhecimento é o resultado de novas formas de encarar, entender e utilizar os objetos e os\n    fenômenos à nossa volta.\n\n Texto-base 3 | página 7 do PDF do capítulo\n\n    Quando nós queremos expressar nosso conhecimento, quando queremos contar algo que sabemos,\n    nós utilizamos uma linguagem que aprendemos ao longo de nossa vida. Usamos, então, o que é\n    chamado de linguagem natural – o português, no nosso caso.\n\n Texto-base 4 | página 9 do PDF do capítulo\n\n    Isso indica que a equação IV não serve para explicar nenhuma das etapas descritas para a calagem\n    e, por essa razão, pode ser desprezada. Então, já respondeu? As equações II e III correspondem à\n    descrição apresentada para as reações que ocorrem na calagem do solo. A alternativa C é a resposta\n    correta para a questão proposta.\n\n Texto-base 5 | página 13 do PDF do capítulo\n\n    É importante que você se familiarize com o trabalho dos cientistas, buscando explicar assuntos tão\n    importantes como a origem da vida e o aparecimento das espécies, a estrutura e as propriedades da\n    matéria, a organização do Universo, a natureza da luz e tantos outros. Freqüentemente, ele não\n    acaba com a apresentação de uma teoria que consiga explicar o que está sendo estudado. Novas\n    descobertas, a revisão de estudos já completados e a troca de informação sobre os estudos e\n    experiências podem resultar em novas teorias, que explicam melhor ou que completam as que já\n    existiam.\n\n Texto-base 6 | página 15 do PDF do capítulo\n\n    Você, que já começou a familiarizar-se com os caminhos da ciência e suas formas de expressão,\n    poderá, agora, compreender outros pontos importantes, relacionados à aplicação da ciência e da\n    tecnologia na solução de problemas.\n\n Texto-base 7 | página 19 do PDF do capítulo\n\n    ainda desempenham um papel de destaque no nível de poluição da Região Metropolitana de São\n    Paulo, principalmente por causa do aumento da frota de veículos. O relatório registra, também, que a\n    emissão de CO em 2001 diminuiu para 1,7 milhão de toneladas. Esse fato pode ser explicado, em\n    parte, pelo aparecimento de novos motores e o uso de catalisadores. Da combustão de gasolina,\n    diesel e outros combustíveis resulta, também, óxido de nitrogênio e hidrocarbonetos, dos quais se\n    origina o ozônio, classificado como poluente secundário, mas não menos importante. Ele é formado\n    pela incidência de luz solar, que promove a quebra das moléculas dos hidrocarbonetos. Quanto maior\n    a luminosidade, maior a porcentagem de quebra de moléculas na atmosfera. Essas moléculas,\n    combinadas com o óxido de nitrogênio, formam o ozônio, considerado como o principal produto do\n    ciclo fotoquímico.\n\n Texto-base 8 | página 23 do PDF do capítulo\n\n    Ao examinar a tabela, você deve notar que as diferenças na composição dos dois iogurtes correm por\n    conta das quantidades de gordura e de proteínas. O iogurte B, desnatado, contém menos gorduras e\n    mais proteínas; portanto, ele pode ser ingerido por pessoas que precisam evitar alimentos\n    gordurosos. O valor calórico dos alimentos é expresso em Kcal (quilocalorias) e representa a\n    quantidade de energia que será produzida por cada um dos alimentos que comemos. O iogurte B tem\n    um valor calórico menor que o iogurte A. Isso quer dizer que o iogurte B fornece menos calorias que o\n    iogurte A.\n\n Síntese para fixação\n • A observação e a elaboração de explicações transformam a vida cotidiana.\n\n • descobertas científicas dependem do contexto social e dos recursos disponíveis.\n\n • o uso do conhecimento pode produzir benefícios ou riscos."},{"area":"Natureza","num":2,"title":"O papel das tecnologias no mundo contemporâneo","body":"Panorama do capítulo\n A produção científica e tecnológica interfere no trabalho, na economia e na organização social.\n\n Conceitos essenciais\n • Inovações alteram processos produtivos e hábitos de consumo.\n\n • o acesso desigual às tecnologias produz diferenças sociais.\n\n • decisões sobre inovação envolvem custos, benefícios e impactos.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 3 do PDF do capítulo\n\n    espantosamente a produtividade, atendendo ao rápido aumento do consumo que temos hoje. Mas\n    sem o desenvolvimento da informática, a robótica pouco avançaria, visto que tanto os movimentos\n    dos robôs como o projeto para desenvolvê-los são realizados por sistemas de informática\n    especializados. Com o aprimoramento das telecomunicações, o fluxo de informações necessárias\n    para o processamento e tomada de decisões aumentou vertiginosamente e, além de transmitir a fala\n    das pessoas, as linhas telefônicas de hoje – com a tecnologia da fibra óptica e dos satélites –\n    transmitem também dados, imagens, músicas, textos etc. É do que se vale a rede mundial de\n    computadores, a internet. Através dela, de casa ou do trabalho, podem-se movimentar contas\n    bancárias, acessar informações em computadores do outro lado do planeta ou conversar com\n    diversas pessoas ao mesmo tempo.\n\n Texto-base 2 | página 6 do PDF do capítulo\n\n    forma: nos estúdios, a luz e o som são captados por câmeras e microfones, sendo convertidos em\n    correntes elétricas que, nos aparelhos da emissora, são transformadas em sinais que são\n    “carregados” pelas ondas eletromagnéticas na sua freqüência característica. Essas ondas,\n    transmitidas em todas as direções, são captadas pelas antenas dos aparelhos receptores de rádio ou\n    de televisão, que separam os sinais e os convertem em correntes elétricas novamente. Ao\n    percorrerem os circuitos internos dos receptores, essas correntes elétricas são amplificadas e\n    produzem os sons e as imagens transmitidas pela emissora. Tudo isso ocorre muito rapidamente.\n\n Texto-base 3 | página 12 do PDF do capítulo\n\n    Os raios gama, emitidos por núcleos de átomos radioativos, finalizam o conjunto das ondas\n    eletromagnéticas, como as ondas com maiores freqüências e maiores energias. Assim como os raios\n    X, os raios gama possuem um alto poder de penetração na matéria, servindo para radiografar peças\n    de aço. Mas materiais como chumbo, concreto e ferro espessos podem ser usados como blindagem,\n    atenuando sua penetração. Quanto mais espessa a blindagem, maior a proteção.\n\n Texto-base 4 | página 18 do PDF do capítulo\n\n    Ao final de toda essa coleta de informações, o serviço da britadeira, felizmente, terminara e Vinícius\n    já podia novamente ser ouvido. Mas depois disso, Antonio preferiu ouvi-lo em volume mais baixo:\n\n Texto-base 5 | página 24 do PDF do capítulo\n\n    Em Campina Grande, os vereadores aprovaram, no final do ano passado uma lei que obriga as\n    escolas públicas a construírem reservatórios para águas pluviais. O intuito, neste caso, é amenizar os\n    efeitos da seca. “Agora, a Câmara deve estender a determinação a todas as edificações da cidade”,\n    afirmou o empresário Elair Antonio Padin, idealizador das piscininhas. (...)\n\n Texto-base 6 | página 29 do PDF do capítulo\n\n    Na figura abaixo, uma cidade brasileira é representada pela cidade A e La Paz, pela cidade B. A\n    cidade brasileira está a uma altitude mais próxima do nível do mar do que La Paz. Logo, a pressão\n    atmosférica da cidade brasileira é maior, pois há uma coluna de ar maior sobre ela, o que significa\n    que há maior quantidade de moléculas de ar por unidade de volume. Os jogadores brasileiros que\n    foram jogar em La Paz\n\n Texto-base 7 | página 34 do PDF do capítulo\n\n    Gilberto Gil nos lembra que também somos do mato, como o pato e o leão. Nossa história mostra que\n    a ciência, junto aos diversos conhecimentos humanos, é instrumento que nos permite usar,\n    racionalmente, esses recursos e a acatarmos, com sabedoria, o ato do abacateiro, conforme pede a\n    música.\n\n Texto-base 8 | página 38 do PDF do capítulo\n\n    Trata-se de uma recomendação bastante polêmica. Uma vez que, por experiência, sabe-se que não\n    se deve colocar qualquer tipo de metal no interior do microondas, pois como a microonda é refletida\n    por metais, isto poderia ocasionar faíscas e riscos de incêndio do aparelho. Apesar disso, alguns\n    fabricantes afirmam que pequenos pedaços de papel alumínio podem envolver pequenas\n    extremidades de alimentos duros, como o osso da coxa do frango, a fim de diminuir a incidência de\n    microondas nesta parte, ocasionando um cozimento mais uniforme. Da mesma forma, como a\n    microonda tem uma penetração limitada nos alimentos, assadeiras quadradas no forno de\n    microondas podem fazer com que o bolo queime nos vértices, nas pontas da assadeira, deixando cru\n    o centro do bolo.\n\n Síntese para fixação\n • Inovações alteram processos produtivos e hábitos de consumo.\n\n • o acesso desigual às tecnologias produz diferenças sociais.\n\n • decisões sobre inovação envolvem custos, benefícios e impactos."},{"area":"Natureza","num":3,"title":"A tecnologia em nosso dia a dia","body":"Panorama do capítulo\n Objetos e serviços comuns dependem de conhecimentos científicos aplicados.\n\n Conceitos essenciais\n • Equipamentos domésticos transformam energia e materiais.\n\n • é preciso considerar eficiência e segurança no uso.\n\n • escolhas individuais de consumo afetam recursos e ambiente.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Todas essas coisas foram inventadas, construídas e melhoradas para aumentar a capacidade do\n    homem em todos os sentidos: algumas para tornar as nossas atividades de trabalho mais eficientes;\n    outras para nos dar maior conforto e prazer; outras para ampliar o nosso tempo de vida.\n\n Texto-base 2 | página 5 do PDF do capítulo\n\n    Atualmente, a quase totalidade dos produtos que consumimos contém uma marca de identificação\n    através de um código de barras. Ele é um conjunto de barras e espaços, estreitos e largos, que são\n    combinados para representar um código de números que identifica um produto. Existem diversos\n    tipos de códigos de barras. Os que seguem o padrão internacional geralmente são de 13 dígitos,\n    podendo variar, dependendo do espaço, até 8 dígitos. Os primeiros dígitos (de um a três) indicam o\n    país (789-Brasil, 779-Argentina, 0 a 9-EUA e Canadá, 80 a 83-Itália, 560-Portugal); os seguintes\n    (quatro a seis) correspondem à empresa; os três a cinco seguintes se referem ao\n\n Texto-base 3 | página 9 do PDF do capítulo\n\n    Em nosso cotidiano, usamos várias linguagens para nos comunicarmos: olhares, gestos corporais,\n    símbolos de cores, desenhos, palavras, letras, números, símbolos científicos etc. Tratamos apenas\n    algumas delas. Entretanto, ficou claro que as formas de representações e conteúdos importantes\n    mudam no tempo e que a efetiva comunicação tem por base a compreensão dos significados das\n    linguagens utilizadas.\n\n Texto-base 4 | página 12 do PDF do capítulo\n\n    compreender melhor o funcionamento dos aparelhos elétricos. Provavelmente, você ou um amigo\n    seu já deve ter “queimado” um aparelho ligando-o em tensão errada. Isso ocorre, principalmente,\n    quando alguém que mora numa cidade onde os aparelhos funcionam em 110V vai para uma outra\n    onde eles funcionam em 220V. Por que os aparelhos elétricos devem ser utilizados conforme as\n    especificações de fabricação?\n\n Texto-base 5 | página 15 do PDF do capítulo\n\n    INSTALAÇÃO O aparelho deve ser ligado em circuito exclusivo (circuito que parte do quadro de\n    distribuição e alimenta diretamente a tomada). Bitolas de fios X distância ao quadro de distribuição.\n\n Texto-base 6 | página 19 do PDF do capítulo\n\n    Estimando os avanços nos meios de transporte Faça as seguintes estimativas: a) velocidade de um\n    animal de carga, de um ônibus e de um avião; b) número de pessoas que podem ser transportadas\n    por um carro, um ônibus e um avião; c) toneladas de carga que podem ser transportadas numa\n    canoa, numa traineira e num cargueiro.\n\n Texto-base 7 | página 21 do PDF do capítulo\n\n    Todas essas transformações de nossa sociedade contemporânea, seja nas relações de trabalho, seja\n    nas relações humanas, seja nos valores morais e éticos, têm a contribuição dos conhecimentos\n    técnico-científico desenvolvidos na área da microeletrônica, base dos atuais avanços das tecnologias\n    de informação e comunicação.\n\n Texto-base 8 | página 26 do PDF do capítulo\n\n    O texto do artigo ainda revela que as áreas reflorestadas por essa empresa têm certificados do\n    Conselho Brasileiro de Manejo Florestal, o que significa que ela contribui para o desenvolvimento\n    sustentável das florestas brasileiras. Entretanto, embora essa atitude seja positiva, a empresa falhou\n    no relacionamento ético com seus consumidores e, portanto, não pode ser considerada socialmente\n    responsável.\n\n Síntese para fixação\n • Equipamentos domésticos transformam energia e materiais.\n\n • é preciso considerar eficiência e segurança no uso.\n\n • escolhas individuais de consumo afetam recursos e ambiente."},{"area":"Natureza","num":4,"title":"Assim caminha a humanidade","body":"Panorama do capítulo\n A história humana envolve transformações materiais, ambientais e tecnológicas.\n\n Conceitos essenciais\n • A produção de bens exige matéria-prima e energia.\n\n • técnicas de transporte e comunicação mudam a sociedade.\n\n • progresso técnico não elimina automaticamente desigualdades ou danos ambientais.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Alguns desses recursos são renováveis, ou seja, são ou podem ser constantemente produzidos, como\n    os alimentos e a água, por exemplo. Outros não – é o caso do petróleo, do gás de cozinha (GLP), dos\n    metais, entre outros, que existem em quantidades limitadas no nosso planeta.\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    A bauxita encontra-se próxima à superfície, em uma profundidade média de 4,5 metros, o que\n    possibilita a sua extração a céu aberto com a utilização de retro-escavadeiras. Porém, antes de se\n    iniciar a extração, alguns cuidados precisam ser tomados para se proteger o meio ambiente. A terra\n    fértil acumulada sobre as jazidas tem que ser removida juntamente com a vegetação e reservada\n    para um futuro trabalho de recomposição do terreno, após a extração do minério.\n\n Texto-base 3 | página 11 do PDF do capítulo\n\n    “Com o índice de 78% (em 2000), o Brasil se mantém entre os países que mais reciclam latas de\n    alumínio no mundo . . . . . . a taxa brasileira reflete o trabalho constante que vem sendo feito na\n    última década para divulgação dos benefícios socioeconômicos proporcionados pela reciclagem, no\n    engajamento de diferentes camadas da sociedade brasileira e no crescimento da consciência\n    ambiental”, afirma o coordenador da Comissão de Reciclagem da ABAL e diretor de Reciclagem da\n    Latasa, José Roberto Giosa”.\n\n Texto-base 4 | página 14 do PDF do capítulo\n\n    • E, por último, a secagem ou a produção de papel: se a celulose for para terceiros, ela é secada,\n    cortada e embalada para ser vendida. Caso a celulose seja transformada em papel na própria\n    empresa, ela recebe a adição de substâncias minerais (chamadas, genericamente, de cargas), que\n    vão conferir características especiais ao produto final.\n\n Texto-base 5 | página 17 do PDF do capítulo\n\n    evaporação recomeça, formando o que os cientistas chamam de ciclo da água. Esse ciclo pode ser\n    afetado por vários fatores, entre eles a poluição das águas, que pode diminuir sua taxa de\n    evaporação e, conseqüentemente, a umidade do ar e quantidade de chuvas na região.\n\n Texto-base 6 | página 21 do PDF do capítulo\n\n     Na etapa de branqueamento das fibras durante a produção de papel e celulose, por exemplo, existe\n     uma alternativa que pode minimizar os problemas ambientais (poluição da água e do ar) gerados\n     pelo uso de cloro e seus derivados, que é o uso de oxigênio em vez do cloro ou seus derivados.\n     Contudo, são poucas as empresas que se utilizam desse recurso. As empresas que não usam o\n     oxigênio alegam que essa é, por enquanto, uma alternativa pouco viável do ponto de vista\n     econômico.\n\n Texto-base 7 | página 24 do PDF do capítulo\n\n     As regras para os avisos nos rótulos – tamanho, dizeres etc. – começaram a ser definidas, mas o\n     resultado prático vai demorar. Depois da decisão final, o texto será transformado em Portaria e\n     publicado no Diário Oficial, entrando em vigor 90 dias depois. Se tudo correr bem, antes do Natal, os\n     brasileiros poderão saber se o que comem foi geneticamente modificado.\n\n Texto-base 8 | página 27 do PDF do capítulo\n\n     Essa atividade tem o objetivo de levá-lo a perceber o impacto ambiental da matéria orgânica (resto\n     de alimentos, esgotos, efluentes de granjas, entre outros) sobre as águas e quebrar o paradigma de\n     que a poluição, de uma maneira geral, é sempre causada por “produtos químicos”. Resposta: o\n     volume de água do rio necessário para estabilizar os 10m3 de esgoto é de 800m3 (800.000 litros). O\n     efeito, a curto prazo, do despejo de esgoto (com alta DBO) nos rios é, normalmente, a proliferação de\n     microorganismos aeróbios que consomem uma grande quantidade de oxigênio da água e,\n     conseqüentemente, causam a morte de peixes e outros seres aquáticos, por asfixia.\n\n Síntese para fixação\n • A produção de bens exige matéria-prima e energia.\n\n • técnicas de transporte e comunicação mudam a sociedade.\n\n • progresso técnico não elimina automaticamente desigualdades ou danos ambientais."},{"area":"Natureza","num":5,"title":"As condições de saúde no Brasil","body":"Panorama do capítulo\n Saúde resulta da interação entre corpo, ambiente, hábitos e condições de vida.\n\n Conceitos essenciais\n • Saneamento e acesso a serviços influenciam a ocorrência de doenças.\n\n • prevenção e informação reduzem riscos.\n\n • indicadores de saúde refletem desigualdades regionais e sociais.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    O Brasil tem conseguido muitos progressos nesses últimos anos. Somos uma nação em\n    desenvolvimento, mas que tem a décima economia do mundo. Para se ter uma idéia do que\n    afirmamos, basta verificar o número de domicílios que tem acesso a serviços essenciais e bens de\n    consumo, atualmente: televisão-87%; geladeira- 84%; telefone-53%. Fazemos parte de um clube\n    seleto de países que conseguem fabricar aviões, lançar satélites, construir hidrelétricas e explorar\n    petróleo em águas profundas. Recentemente, foi anunciado que cientistas brasileiros decifraram o\n    genoma (conjunto de genes) de uma bactéria que\n\n Texto-base 2 | página 6 do PDF do capítulo\n\n    é a taxa de mortalidade infantil. Pode-se, portanto, concluir que pode haver uma relação entre maior\n    número de mães analfabetas em uma determinada região e um aumento na taxa de mortalidade\n    infantil.\n\n Texto-base 3 | página 10 do PDF do capítulo\n\n    As características que são transmitidas de pais para filhos estão contidas nas duas células\n    reprodutoras, o espermatozóide e o óvulo, que se unem e dão origem ao embrião. Mas a Dolly não\n    nasceu a partir dessas duas células. Essa é a grande diferença.\n\n Texto-base 4 | página 13 do PDF do capítulo\n\n    É possível afirmar que, de cada 10 crianças que nascem no Brasil, aproximadamente três são filhas\n    de mães adolescentes? Considerando que as mães de 14 a 19 anos estão no período da\n    adolescência, vamos calcular que porcentagem seus filhos representam dentro do total de crianças\n    nascidas no Brasil. Basta verificar qual é o total de filhos nascidos de mães de 14 a 19 anos (primeira\n    coluna da tabela) e calcular que porcentagem esse número representa dentro do total de filhos\n    nascidos de mães brasileiras, o que inclui todas as faixas etárias (última coluna). Se essa\n    porcentagem estiver acima de 20% e próxima, portanto, de 30%, o que corresponde a 30 em 100\n    (ou, simplificando, 3 em 10), podemos considerar a afirmativa correta.\n\n Texto-base 5 | página 17 do PDF do capítulo\n\n    Qual é a importância da escola em sua vida? As estatísticas do IBGE mostram que quanto maior o\n    número de anos que as adolescentes permanecem na escola (9 a 11 anos), diminui em 14% o risco\n\n    de ficarem grávidas.\n\n Texto-base 6 | página 19 do PDF do capítulo\n\n    A partir das informações citadas anteriormente, forneça argumentos para explicar por que pessoas\n    malnutridas, principalmente com deficiência de ferro e cálcio na alimentação, sofrem mais danos\n    com esse tipo de intoxicação. Lembre-se do local onde o chumbo fica depositado em maior\n    quantidade no organismo e em que células do sangue ele causa problemas, e você já sabe a\n    resposta.\n\n Texto-base 7 | página 24 do PDF do capítulo\n\n    Muito lixo vai para as ruas, terrenos baldios, calçadas, entopem bueiros, provocam o assoreamento\n    dos leitos dos rios, levando a enchentes e fazendo proliferar animais como ratos e insetos,\n    transmissores de doenças. O lixo é uma fonte de doenças como parasitoses, diarréia, hepatite,\n    leptospirose e até dengue. O restante do lixo é recolhido e transportado pela prefeitura. Os serviços\n    de coleta de lixo atingiam, em 1998, 92,45% das residências (Fonte IBGE). Esse número é menor nas\n    regiões Norte e Nordeste. O gráfico a\n\n Texto-base 8 | página 28 do PDF do capítulo\n\n    Clonagem terapêutica — a favor: frase nº 3, já que qualquer célula pode realmente ser clonada e\n    gerar um novo ser; contra: frase nº 1, porque considera que a vida começa no momento da\n    fecundação e se está destruindo um ser humano, mesmo que seja constituído por poucas células.\n    Clonagem humana — a favor: frase nº 2, porque acredita que qualquer pesquisa deve ser realizada\n    em função das descobertas científicas; contra: frase nº 4, visão ética que se preocupa com as\n    conseqüências futuras de nascerem clones humanos defeituosos.\n\n Síntese para fixação\n • Saneamento e acesso a serviços influenciam a ocorrência de doenças.\n\n • prevenção e informação reduzem riscos.\n\n • indicadores de saúde refletem desigualdades regionais e sociais."},{"area":"Natureza","num":6,"title":"Em busca do conhecimento: o fazer científico","body":"Panorama do capítulo\n Conhecer cientificamente envolve formular problemas, levantar hipóteses e confrontá-las com\n evidências.\n\n Conceitos essenciais\n • Observações precisam ser registradas e comparadas.\n\n • experimentos devem controlar variáveis quando possível.\n\n • conclusões são revisáveis e dependem da qualidade das evidências.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 3 do PDF do capítulo\n\n    Não são só os cientistas que usam técnicas e processos para estabelecer e solucionar problemas.\n    Toda vez que temos um problema para resolver, como um aparelho que deixou de funcionar ou um\n    sintoma físico anormal que estamos sentindo, (e em cada caso procuramos fazer um diagnóstico),\n    estamos, mesmo sem saber, usando procedimentos empregados pela ciência. Observamos, fazemos\n    experimentos (verificamos o fusível do aparelho), obtemos dados (medimos a temperatura),\n    levantamos hipóteses, suposições tais como: será uma gripe? Terá sido um curto- circuito?\n\n Texto-base 2 | página 9 do PDF do capítulo\n\n    exemplo que pode nos ajudar a interpretar os dados acima é uma linha do tempo comentada.\n    Podemos representar, numa única linha, do tamanho que quisermos, o tempo que precisar, desde\n    que respeitemos a escala.\n\n Texto-base 3 | página 16 do PDF do capítulo\n\n    “Indústrias e agricultores não têm o costume de reciclar a água que usam e as companhias de\n    tratamento e distribuição governamentais ignoram os quase 70% de água que não chegam às\n    torneiras por causa dos vazamentos”.\n\n Texto-base 4 | página 21 do PDF do capítulo\n\n    a) Analisando a tabela, como você explica os resultados obtidos para a cidade de São Paulo? b) E\n    para a divisa de Promissão e José Bonifácio e Res. Guarapiranga? Com a ajuda de um mapa, tente\n    interpretar, levantando hipóteses, as razões que justificariam esses resultados.\n\n Texto-base 5 | página 25 do PDF do capítulo\n\n    a) Como é a situação das várias regiões do Brasil em relação aos cuidados com o esgoto? Em quais\n    regiões o problema é maior? E menor? Por quê? b) Quais as conseqüências dessa situação?\n\n Texto-base 6 | página 29 do PDF do capítulo\n\n    sabor, os corantes, os estabilizantes e aromatizantes, como você viu no chocolate, e muitos outros.\n    Cada um é usado para uma finalidade diferente e todos são substâncias químicas, mas nenhum deles\n    tem o propósito de nutrir. Observe a tabela abaixo, que exemplifica alguns aditivos usados para\n\n    conservar alimentos.\n\n Texto-base 7 | página 31 do PDF do capítulo\n\n    b) Que ainda há muita gente não usando camisinha nas relações sexuais, que usuários de droga\n    continuam não se protegendo e contraindo a doença por uso comum de seringas e, além disso, pode\n    ter aumentando o número de usuários.\n\n Texto-base 8 | página 33 do PDF do capítulo\n\n    b) Há muita gente recebendo água sem tratamento em todas as regiões do país, com exceção da\n    Centro-Oeste. Repare que as regiões Norte, Nordeste e Sul têm menores quantidades de água\n    distribuída e mesmo assim, muita sem tratamento. Isto indica que a probabilidade do contágio de\n    doenças transmitidas pela água é muito grande, o que prejudica a saúde da população.\n\n Síntese para fixação\n • Observações precisam ser registradas e comparadas.\n\n • experimentos devem controlar variáveis quando possível.\n\n • conclusões são revisáveis e dependem da qualidade das evidências."},{"area":"Natureza","num":7,"title":"Conhecimentos físicos e a vida atual","body":"Panorama do capítulo\n A Física ajuda a interpretar movimento, forças, energia e fenômenos do cotidiano.\n\n Conceitos essenciais\n • Grandezas e medidas permitem descrever fenômenos.\n\n • máquinas e dispositivos aplicam princípios físicos.\n\n • compreender consumo e transformação de energia apoia escolhas responsáveis.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Quando estamos na cozinha, basta uma distração para acabarmos queimados com o óleo que\n    “espirrou” ou com o cabo da colher que ficou dentro da panela. Esses fenômenos podem ser\n    explicados com os conceitos de calor, temperatura, dilatação e as formas de transmissão de energia\n    térmica, que também explicam as trocas de energia térmica em sistemas tecnológicos, como o\n    motor, e em sistemas naturais, como nosso corpo e a atmosfera.\n\n Texto-base 2 | página 5 do PDF do capítulo\n\n    Quando queremos medir tempos menores que algumas frações de segundo, a inércia das\n    engrenagens e dos mecanismos do relógio não permite que se consiga a regularidade necessária\n    para medir o tempo.\n\n Texto-base 3 | página 10 do PDF do capítulo\n\n    Geladeiras Para diminuir as perdas térmicas de uma geladeira, podem ser tomados alguns cuidados\n    operacionais: I. Distribuir os alimentos nas prateleiras deixando espaços vazios entre eles, para que\n    ocorra a circulação do ar frio para baixo e do quente para cima. II. Manter as paredes do congelador\n    com camada bem espessa de gelo, para que o aumento da massa de gelo aumente a troca de calor\n    no congelador. III. Limpar o radiador (“grade” na parte de trás) periodicamente, para que a gordura e\n    a poeira que nele se depositam não reduzam a transferência de calor para o ambiente. Para uma\n    geladeira tradicional é correto indicar, apenas: a) a operação I. b) a operação II. c) as operações I e II.\n    d) as operações I e III. e) as operações II e III.\n\n Texto-base 4 | página 13 do PDF do capítulo\n\n    Esses equipamentos normalmente utilizam a compressão do ar para frear, aumentando o tempo do\n    freamento com a “deformação” do ar, durante a compressão. Assim, uma força pequena atua\n\n Texto-base 5 | página 17 do PDF do capítulo\n\n    Essas máquinas nos permitem ainda alcançar sonhos que o trabalho animal jamais nos possibilitaria,\n    como a conquista do espaço. Conseguimos fazer algo que nenhum outro animal na Terra consegue,\n    que é escapar da ação da gravidade terrestre e sair do nosso planeta.\n\n Texto-base 6 | página 22 do PDF do capítulo\n\n    número de dias em que o equipamento é utilizado no mês. O consumo é apresentado em quilowatts-\n    hora, como aparece nas contas de energia elétrica. Um quilowatt-hora (kWh) corresponde à energia\n    elétrica transformada em calor ou trabalho por um aparelho com potência de 1.000 watts sendo\n    utilizado durante 1 hora.\n\n Texto-base 7 | página 27 do PDF do capítulo\n\n    1) Analisando o esquema, é possível identificar que se trata de uma usina: a) Hidrelétrica, porque a\n    água corrente baixa a temperatura da turbina. b) Hidrelétrica, porque a usina faz uso da energia\n    cinética da água. c) Termoelétrica, porque no movimento das turbinas ocorre aquecimento. d) Eólica,\n    porque a turbina é movida pelo movimento da água. e) Nuclear, porque a energia é obtida do núcleo\n    das moléculas de água.\n\n Texto-base 8 | página 30 do PDF do capítulo\n\n    A conservação da energia ocorre sempre, em qualquer sistema, em qualquer processo. Esse é um\n    princípio fundamental da ciência atual. Não há processos em que não ocorra conservação da energia.\n\n Síntese para fixação\n • Grandezas e medidas permitem descrever fenômenos.\n\n • máquinas e dispositivos aplicam princípios físicos.\n\n • compreender consumo e transformação de energia apoia escolhas responsáveis."},{"area":"Natureza","num":8,"title":"Química, natureza e tecnologia","body":"Panorama do capítulo\n A Química estuda substâncias, suas propriedades e transformações.\n\n Conceitos essenciais\n • Materiais naturais e industrializados possuem diferentes composições.\n\n • reações químicas participam da produção de alimentos e produtos.\n\n • resíduos e processos químicos exigem cuidados ambientais.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Você já parou para pensar sobre os materiais que foram utilizados para a construção de sua moradia?\n    Dentre esses, o cobre é muito utilizado em ferragens, portas e adornos. Os fios utilizados para\n    conduzir a eletricidade (em sua casa, nas cidades, nos brinquedos, nos aparelhos eletrodomésticos)\n    são de cobre metálico, ou seja, não combinado com outras substâncias.\n\n Texto-base 2 | página 5 do PDF do capítulo\n\n    Nessa transformação, o elemento cobre é o mesmo antes e depois. A modificação ocorre na maneira\n    como ele se apresenta: o seu estado físico. Essa transformação, é denominada fusão.\n\n Texto-base 3 | página 8 do PDF do capítulo\n\n    a proporção que contenham de cada componente, os diferentes tipos de bronze apresentam\n    propriedades também diversas, como dureza, plasticidade, resistência à tração e à corrosão, etc.\n\n Texto-base 4 | página 11 do PDF do capítulo\n\n    Se compararmos o estado inicial e final, dizemos que houve uma transformação, pois mudou a cor,\n    houve a produção de um gás e houve absorção ou consumo de energia térmica. Podemos concluir\n    que houve alteração na natureza das substâncias, com a formação de novas substâncias. Portanto,\n    este processo é uma transformação química.\n\n Texto-base 5 | página 14 do PDF do capítulo\n\n    Se a extração desses minerais for viável economicamente, ou seja, se houver lucro, a concentração\n    de minerais nas rochas é considerada minério. Em outras palavras, o minério é uma rocha, pois é\n    formado por minerais, mas é uma rocha que tem valor econômico.\n\n Texto-base 6 | página 18 do PDF do capítulo\n\n    Atualmente, a primeira fase do processo é o aquecimento da calcopirita em um forno, onde o sulfeto\n    de ferro é transformado em óxido de ferro. Em seguida, separa-se a escória (materiais\n    desnecessários) e o material contendo o cobre sofre novo aquecimento. Esta etapa garante que todo\n    óxido de cobre formado anteriormente seja transformado em cobre metálico.\n\n Texto-base 7 | página 22 do PDF do capítulo\n\n    Vamos pensar no caso da metalúrgica. Vamos comparar a quantidade de calor desprendido pela\n    queima do GLP e do óleo combustível? Como podemos observar, a tabela nos indica que a queima de\n    1 kg de GLP libera 11.750 kcal. Já 1 kg de óleo combustível libera 10.090 kcal. Quantas kcal foram\n    utilizadas, na metalurgia do cobre, no Brasil em 2001, sabendo-se que foram queimados 18.632 t de\n    óleo combustível?\n\n Texto-base 8 | página 27 do PDF do capítulo\n\n    Construa uma seqüência representando os vários pontos da cadeia produtiva do cobre, desde a\n    extração na natureza até o fio de eletricidade e a reintrodução da sucata na cadeia produtiva. Em\n    seguida, discuta os possíveis destinos da sucata de cobre (lixo).\n\n Síntese para fixação\n • Materiais naturais e industrializados possuem diferentes composições.\n\n • reações químicas participam da produção de alimentos e produtos.\n\n • resíduos e processos químicos exigem cuidados ambientais."},{"area":"Natureza","num":9,"title":"Biodiversidade e meio ambiente","body":"Panorama do capítulo\n A diversidade dos seres vivos está relacionada ao equilíbrio dos ecossistemas e às atividades humanas.\n\n Conceitos essenciais\n • Espécies interagem entre si e com o ambiente.\n\n • a degradação de habitats ameaça a biodiversidade.\n\n • conservação exige compreender causas e consequências de intervenções humanas.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Pois é, a diversidade biológica (ou biodiversidade) refere-se à variedade de vida no planeta terra,\n    incluindo a variedade genética, a variedade de espécies e a variedade de ecossistemas.\n\n Texto-base 2 | página 7 do PDF do capítulo\n\n    Observe o mapa de localização das florestas tropicais (Figura 5) e relacione com as informações que\n    já vimos sobre o clima. Que fatores climáticos contribuem para que a biodiversidade, nessa faixa do\n    planeta, onde ocorrem estas florestas, seja maior do que em outras regiões?\n\n Texto-base 3 | página 15 do PDF do capítulo\n\n    Estas grandes árvores atingem até 60 metros de altura, como uma massaranduba ou uma\n    castanheira. Imagine o tamanho de suas flores. E os frutos que contêm as sementes? Devem ser\n    grandes também, não é? Agora imagine que tipo de animal faz a polinização (leva os grãos de pólen\n    de uma planta para outra) destas flores. E a dispersão das sementes desses frutos grandes?\n\n Texto-base 4 | página 19 do PDF do capítulo\n\n    de anos surgiram os primeiros organismos com células complexas. Há 600 milhões, os primeiros\n    animais. Há 450 milhões de anos, as primeiras plantas terrestres, insetos, anfíbios (que evoluíram\n    dos peixes) e répteis. Em seguida, as aves e os mamíferos. Os primatas antropóides têm,\n    aproximadamente, 2 milhões de anos.\n\n Texto-base 5 | página 23 do PDF do capítulo\n\n    A biodiversidade é uma das propriedades fundamentais da natureza, responsável pelo equilíbrio e\n    estabilidade dos ecossistemas, e fonte de imenso potencial de uso econômico. A biodiversidade é a\n    base das atividades agrícolas, pecuárias, pesqueiras e florestais e, também, a base para a\n    estratégica indústria da biotecnologia. A diversidade biológica possui, além de seu valor\n\n Texto-base 6 | página 26 do PDF do capítulo\n\n    Uma das grandes ameaças à biodiversidade da floresta amazônica é a expansão das grandes\n    plantações de soja do sul do Pará. A atividade de extração indiscriminada de madeira, associada às\n    queimadas para expansão de áreas agrícolas, também aumenta significativamente as perdas\n    florestais.\n\n Texto-base 7 | página 29 do PDF do capítulo\n\n    Já sabemos que os solos florestais são pobres em nutrientes e que os organismos do solo\n    decompõem rapidamente os nutrientes que chegam. No exercício 18, você identificou o que\n    acontece com o solo quando a floresta é substituída por uma monocultura. Agora tente explicar\n    porque a agricultura baseada em Sistemas Agroflorestais é mais adequada para regiões florestais do\n    que grandes lavouras de monocultura.\n\n Texto-base 8 | página 31 do PDF do capítulo\n\n    Esta atividade é uma continuação da atividade 14 e requer que você perceba que estas aves\n    possuem um ancestral comum (que provavelmente existiu quando os continentes estavam juntos) e\n    que, com a separação dos continentes, sofreu pressões ambientais semelhantes em cada continente\n    dando origem a novas formas adaptadas.\n\n Síntese para fixação\n • Espécies interagem entre si e com o ambiente.\n\n • a degradação de habitats ameaça a biodiversidade.\n\n • conservação exige compreender causas e consequências de intervenções humanas."},{"area":"Linguagens","num":1,"title":"Publicidade, entretenimento e outros sistemas","body":"Panorama do capítulo\n Mensagens combinam palavras, imagens e sons para produzir sentidos.\n\n Conceitos essenciais\n • A publicidade busca influenciar percepções e escolhas.\n\n • diferentes veículos apresentam pontos de vista.\n\n • interpretar mensagens exige observar público, finalidade e contexto.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Olhando para este anúncio, talvez sintamos vontade de comer maçã ou um doce feito da fruta. Mas é\n    curioso: não estamos vendo uma maçã na nossa frente. Chegamos a sentir vontade de comer, uma\n    vez que a maçã desenhada parece apetitosa e o nome da empresa é “Docemel”. Porém, a fruta que\n    está aí é apenas um pedaço de papel desenhado.\n\n Texto-base 2 | página 5 do PDF do capítulo\n\n    Mais do que um rótulo de garrafa Analise o rótulo de garrafa acima, do ponto de vista das linguagens\n    verbal e visual. Relacione o sentido do que está escrito (o que as palavras ou frases querem dizer)\n    com aspectos visuais (o desenho abaixo da expressão “sem gás”, os tipos de letras ou qualquer outro\n    aspecto que você considerar relevante).\n\n Texto-base 3 | página 8 do PDF do capítulo\n\n    Se há crise no Oriente Médio, podemos estar vendo o desencadear de uma guerra sangrenta, com\n    conseqüências políticas, econômicas e sociais no mundo (os países árabes, localizados no Oriente\n    Médio, são grandes fornecedores de petróleo, matéria-prima da gasolina, usada no mundo inteiro, e a\n    crise pode ter inúmeras conseqüências).\n\n Texto-base 4 | página 9 do PDF do capítulo\n\n    Ela é exatamente igual nas duas? Não. Pode ser parecida. Na televisão: quando acompanhamos um\n    fato na emissora A ou na emissora B, vemos a mesma coisa? As imagens são as mesmas, o\n    apresentador é o mesmo? Os sons que acompanham as imagens são os mesmos? As idéias que os\n    repórteres apresentam são formuladas do mesmo jeito? Com certeza, não.\n\n Texto-base 5 | página 11 do PDF do capítulo\n\n     Não podemos e nem devemos dar uma resposta definitiva a tais perguntas, mas podemos formular\n     algumas hipóteses. Olhe para o lado agora. Talvez tudo em volta lhe pareça muito natural, muito\n     “certinho”. Pense um pouco. Você faz tudo o que gostaria de fazer? E por que não faz? Se você não\n     tivesse tomado essa ou aquela atitude lá atrás na sua vida, será que a sua vida seria diferente agora,\n     será que ela seria melhor ou pior?\n\n Texto-base 6 | página 12 do PDF do capítulo\n\n     Você pode estar se perguntando a essa altura: “E a beleza? Uma obra de arte não tem que ser\n     bonita? A gente vê uns quadros por aí, parecem umas tintas jogadas em cima da tela... Será que isso\n     é arte? ”\n\n Texto-base 7 | página 13 do PDF do capítulo\n\n     E por que isso acontece? Como uma história inventada, que se divide em tantos capítulos, pode ser\n     tão facilmente acompanhada pelas mais diferentes pessoas, com diferentes níveis de escolaridade?\n\n Texto-base 8 | página 14 do PDF do capítulo\n\n     No jornal escrito há o setor de classificados. Mas as notícias de jornal não têm uma relação direta\n     com os produtos que estão sendo vendidos nos classificados. Pegue uma revista e um jornal. Procure\n     uma página com o anúncio de algum produto. Veja se há uma relação direta entre as notícias e os\n     produtos anunciados.\n\n Síntese para fixação\n • A publicidade busca influenciar percepções e escolhas.\n\n • diferentes veículos apresentam pontos de vista.\n\n • interpretar mensagens exige observar público, finalidade e contexto."},{"area":"Linguagens","num":2,"title":"As línguas estrangeiras modernas em nossa","body":"sociedade\n\n Panorama do capítulo\n Línguas estrangeiras permitem acesso a culturas, informações e interações sociais.\n\n Conceitos essenciais\n • Compreender textos depende também de contexto e conhecimentos prévios.\n\n • palavras semelhantes podem ter sentidos diferentes.\n\n • usos linguísticos variam conforme situação e interlocutor.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Veja só outra situação bastante corriqueira. Quando você liga seu aparelho de televisão para assistir\n    a um jogo de futebol da nossa seleção, é bem provável que queira ver o time marcar\n\n Texto-base 2 | página 3 do PDF do capítulo\n\n    BOMBOM: do francês bonbon, guloseima. Nome genérico com o qual denominamos balas, chocolates,\n    doces. É freqüente o francesismo bonbonnière para designar as pequenas lojas especializadas na\n    venda desses produtos.\n\n Texto-base 3 | página 5 do PDF do capítulo\n\n    Claro, pois ninguém espera ler, em um anúncio, algo como “Venha jantar em um de nossos\n    restaurantes sujos e horríveis”. O anúncio quer vender algo e, por essa razão, a linguagem deve\n    seduzir e atrair o possível comprador.\n\n Texto-base 4 | página 8 do PDF do capítulo\n\n    É bastante comum ourvirmos a seguinte afirmação: “Eu me viro bem em Espanhol, porque se parece\n    muito com o Português. Na verdade, é só usar as palavras do Português com a pronúncia do Espanhol\n    e está tudo resolvido.” Ora, isso não é bem verdade. De fato, há muitas semelhanças entre\n\n Texto-base 5 | página 10 do PDF do capítulo\n\n    Vamos discutir um pouco mais sobre isso. Você provavelmente fez uso das imagens e das palavras\n    cognatas, não é mesmo? É o caso da diferença entre toothpaste e toothbrush.\n\n Texto-base 6 | página 11 do PDF do capítulo\n\n    Sempre que você vir outros textos – notícias, marcas, nomes de estabelecimentos comerciais,\n    anúncios – com termos ou expressões em línguas estrangeiras, pare e pense nas intenções e\n    significados desse uso.\n\n Texto-base 7 | página 13 do PDF do capítulo\n\n    Assim, na produção de uma única artista, vemos, ao mesmo tempo, marcas de sua inserção no\n    mercado cultural mundial e da afirmação de suas origens. É o prato de saladas de que falamos\n    anteriormente.\n\n Texto-base 8 | página 17 do PDF do capítulo\n\n    O diálogo se passa entre a) um usuário de computador e um técnico especializado. b) um usuário de\n    videocassete e um representante técnico. c) um motorista de táxi e um mecânico. d) um dono de loja\n    e um marceneiro.\n\n Síntese para fixação\n • Compreender textos depende também de contexto e conhecimentos prévios.\n\n • palavras semelhantes podem ter sentidos diferentes.\n\n • usos linguísticos variam conforme situação e interlocutor."},{"area":"Linguagens","num":3,"title":"Quero o meu corpo de volta!","body":"Panorama do capítulo\n A linguagem corporal participa da expressão, da identidade e da vida social.\n\n Conceitos essenciais\n • Práticas corporais são influenciadas por cultura e época.\n\n • padrões de corpo podem produzir exclusões.\n\n • movimento, saúde e convivência envolvem escolhas e valores.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Note, por exemplo, que alguns usam roupas com nomes engraçados. Mulheres jovens costumam\n    vestir trajes mais leves, deixando partes do corpo à mostra, enquanto as de mais idade usam roupas\n    maiores, de cores diferentes. Alguns homens, dependendo da função que ocupam nos seus\n    trabalhos, usam ternos escuros, enquanto outros, uniformes ou roupas comuns. Qual a razão disso?\n    Se você observar bem, poderá notar que as roupas caracterizam as pessoas; é como se colocassem\n    sobre elas determinadas marcas: idade, profissão, situação social. Assim, é o corpo que está sendo\n    marcado.\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    Você poderá pensar também na sua própria atividade. Verifique se você executa atividades que\n    repetem movimentos específicos de sua profissão, ou seja, existentes somente na atividade que você\n    faz, desnecessários em outra situação do dia-a-dia? E, nesse caso, estão os atos de dirigir, costurar,\n    trabalhar numa máquina, trabalhar na lavoura, pintar, digitar etc.\n\n Texto-base 3 | página 5 do PDF do capítulo\n\n    Há também outra questão quando se pensa na modificação do ambiente em que vivemos. Como lidar\n    com a velocidade das modificações, quando todos sabem que levamos muito tempo para aprender a\n    andar de bicicleta, a dirigir um automóvel, a costurar em uma máquina de pedal, a usar um\n    determinado instrumento?\n\n Texto-base 4 | página 6 do PDF do capítulo\n\n    afirmar que essas situações não são usadas da mesma maneira ou com a mesma intenção. Reflita\n    sobre isso e tente localizar o lugar desses mesmos movimentos (ou parecidos) na sociedade atual.\n\n Texto-base 5 | página 8 do PDF do capítulo\n\n    Faça algumas comparações entre os seus movimentos e os movimentos das pessoas que estão à sua\n    volta; tente entender os caminhos que marcaram as diferenças e o surgimento das igualdades.\n\n Texto-base 6 | página 9 do PDF do capítulo\n\n    O que é preciso fazer, quando se permanece muito tempo sentado? O que é preciso fazer, quando se\n    executam movimentos repetitivos por muito tempo? Seu bem-estar irá depender disso.\n\n Texto-base 7 | página 10 do PDF do capítulo\n\n    Pode-se dizer que a importância disso é tão grande que chega a invadir até a nossa forma de falar.\n    Preste atenção, por exemplo, nas expressões abaixo e procure identificar o que elas querem dizer:\n    “Estou na área! Em time que está ganhando não se mexe! Olhe lá hein, não vá pisar na bola! Ei,\n    cuidado que o patrão pode te dar um cartão vermelho!”\n\n Texto-base 8 | página 12 do PDF do capítulo\n\n    Graças à possibilidade que a cultura esportiva tem de possibilitar, por meio dos movimentos, a\n    participação de culturas diferentes é que tem aumentado a freqüência de pessoas às atividades\n    esportivas a cada ano que passa. Um bom exemplo é a tradicional Corrida de São Silvestre realizada\n    no último dia do ano na cidade de São Paulo. Esta prova recebe atletas estrangeiros, pessoas que\n    praticam atividade física constantemente e muitos que estão apenas participando com a intenção de\n    completar a corrida.\n\n Síntese para fixação\n • Práticas corporais são influenciadas por cultura e época.\n\n • padrões de corpo podem produzir exclusões.\n\n • movimento, saúde e convivência envolvem escolhas e valores."},{"area":"Linguagens","num":4,"title":"A arte no cotidiano do homem","body":"Panorama do capítulo\n A arte é uma forma de expressão e interpretação da experiência humana.\n\n Conceitos essenciais\n • Obras artísticas dialogam com contextos históricos.\n\n • diferentes linguagens artísticas produzem sentidos.\n\n • o acesso à arte participa da construção cultural e identitária.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    A Arte envolve sempre imaginação e criatividade de quem a faz e é essencial ao ser humano como\n    mais uma forma de expressar suas idéias ou emoções. Por quê? Porque possui uma maneira própria\n    de traduzir as idéias e emoções humanas, por meio de suas diferentes linguagens artísticas, que\n    utilizam as imagens na pintura, na escultura, na arquitetura, os sons e os ritmos na música, a palavra\n    na literatura, ou os movimentos na dança e no teatro.\n\n Texto-base 2 | página 3 do PDF do capítulo\n\n    Você já reparou, ao passar por uma banca de jornais, quantas revistas apresentam “soluções” para\n    que se consiga uma boa forma física? Note que há uma valorização muito grande do que seria o\n    “corpo perfeito”. Todo ser humano deseja ser belo dentro dos padrões da sociedade em que vive.\n    Atualmente, o culto à beleza pode virar uma idéia fixa, a ponto de levar mulheres a se tornarem\n    esqueléticas ou siliconadas e homens a desenvolverem demasiadamente seus músculos. Isso nos\n    leva a constatar que o belo, como\n\n Texto-base 3 | página 6 do PDF do capítulo\n\n    Os meios de comunicação são responsáveis, muitas vezes, por divulgar e até mesmo manipular os\n    padrões de beleza. Através da televisão, revistas ou jornais, podemos ter acesso ao que está ou não\n    na moda, ao que é considerado feio ou bonito. Muitas vezes, determinados conceitos nos são\n    impostos por propagandas, que nos levam a usar um sapato ou uma roupa pelo simples fato de\n    estarem na moda, mesmo não nos agradando tanto. Já aconteceu alguma vez com você, ao pegar\n    uma antiga foto sua, se perguntar como teve coragem de se vestir daquela maneira? Isso revela\n    como até o gosto pessoal é influenciado pela sociedade e pelos meios de comunicação.\n\n Texto-base 4 | página 7 do PDF do capítulo\n\n    Você sabia que o Brasil também possui uma Arte pré-histórica, que teve origem muito antes de ele\n    ser descoberto pelos portugueses? Podemos encontrar sítios arqueológicos em vários locais do\n    território brasileiro. Será que existe algum próximo à sua cidade? Infelizmente, muitos deles não\n    estão em bom estado de conservação e outros chegaram até a ser destruídos. Isso aconteceu com\n    algumas grutas em Minas Gerais, quando fábricas de cimento tiraram delas o calcário para se\n    abastecer.\n\n Texto-base 5 | página 8 do PDF do capítulo\n\n    Quantas vezes você já viu ou participou de procissões, festas e cultos religiosos? Você já deve ter\n    observado como a música está sempre presente nessas ocasiões e como ela mexe com a\n    sensibilidade e a emoção das pessoas, aproximando-as de um deus em quem elas acreditam.\n\n Texto-base 6 | página 10 do PDF do capítulo\n\n    Para que você entenda melhor o presente, é muitas vezes necessário que conheça um pouco do\n    passado. Saiba que o teatro surgiu na Grécia, por volta dos séculos VII ou VI a.C. A multidão sentava\n    nas arquibancadas, ao ar livre, para ouvir os poetas e os atores das tragédias e das comédias.\n\n Texto-base 7 | página 11 do PDF do capítulo\n\n    Les Demoiselles d’Avignon foi o quadro revolucionário que deu início a esse movimento artístico\n    chamado Cubismo. Você já ouviu falar nesse movimento? Ele surgiu no início do século XX, mudando\n    toda a Arte. Mas como ocorreu isso? Foi através da simplificação e geometrização das figuras.\n\n Texto-base 8 | página 14 do PDF do capítulo\n\n    A Arte Moderna vai buscar no nacionalismo as raízes brasileiras. O que você compreende como\n    nacionalismo? É aquele sentimento que nos une, por exemplo, durante uma copa do mundo e nos faz\n    torcer apaixonadamente pela nossa seleção de futebol. É uma sensação de se pertencer a um\n    determinado grupo. Portanto, nacionalismo é a valorização de tudo o que é de um povo.\n\n Síntese para fixação\n • Obras artísticas dialogam com contextos históricos.\n\n • diferentes linguagens artísticas produzem sentidos.\n\n • o acesso à arte participa da construção cultural e identitária."},{"area":"Linguagens","num":5,"title":"Quando as palavras resolvem fazer arte...","body":"Panorama do capítulo\n A linguagem literária explora sonoridade, imagens, ritmo e múltiplos sentidos.\n\n Conceitos essenciais\n • Recursos expressivos transformam usos cotidianos da língua.\n\n • gêneros literários organizam diferentes experiências.\n\n • a leitura considera tanto o texto quanto seu contexto.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Há muitas formas de arte para atender às necessidades humanas: a pintura, a música, a escultura, a\n    dança... Você consegue aumentar essa lista? Aqui, neste capítulo, vamos falar de uma dessas\n    expressões artísticas, a LITERATURA.\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    Numa primeira leitura, o texto apresenta-se, nos primeiros 11 versos, como uma lista de definições\n    do amor. A repetição constante do termo “É” reforça esse sentido. No último terceto, a conclusão\n    iniciada pelo termo “mas” que normalmente é utilizado na fala do dia a dia com o sentido de\n    oposição de idéias, é uma longa pergunta do poeta.\n\n Texto-base 3 | página 5 do PDF do capítulo\n\n    Luís de Camões é um dos autores mais valorizados em Língua Portuguesa. Sua história é uma\n    verdadeira aventura: nem sequer sabemos exatamente quando nasceu, talvez em 1524 ou 1525,\n    talvez na cidade de Lisboa, com certeza, em Portugal.\n\n Texto-base 4 | página 7 do PDF do capítulo\n\n    texto literário está escrito. Certos textos são difíceis de entender, porque eles foram escritos há\n    muito tempo. A maneira como se escrevia naquela época pode ser bastante diferente da atual. O\n    envelhecimento de certas formas de expressão dificulta ao leitor a compreensão do texto.\n\n Texto-base 5 | página 8 do PDF do capítulo\n\n    Às vezes, o narrador valoriza mais as ações e o tempo que elas levam para acontecer – é o que\n    chamamos de tempo cronológico; outras vezes, o narrador considera mais importante a sensação de\n    tempo que as personagens sentem e estrutura a sua narrativa em torno desse tempo psicológico.\n    Com certeza, você já sentiu, em certas ocasiões, que um minuto (tempo cronológico) parece durar\n    horas (a sensação do tempo psicológico).\n\n Texto-base 6 | página 11 do PDF do capítulo\n\n    Em músicas! justamente esta palavra do médico deu ao mestre um pensamento. Logo que ficou só,\n    com o escravo, abriu a gaveta onde guardava desde 1779 o canto esponsalício começado. Releu\n    essas notas arrancadas a custo e não concluídas. E então teve uma idéia singular: - rematar a obra\n\n    agora, fosse como fosse; qualquer coisa servia, uma vez que deixasse um pouco de alma na terra.\n\n Texto-base 7 | página 14 do PDF do capítulo\n\n    Antes de nos aprofundarmos no poema, tente recapitular o que já aprendeu, identificando quantos\n    versos possui o poema, quantas estrofes e qual o esquema de rimas do poema.\n\n Texto-base 8 | página 16 do PDF do capítulo\n\n    romanos. Talvez você concorde com eles, principalmente depois de ler o texto a seguir, retirado da\n    peça Juiz de Paz na Roça, do escritor brasileiro Martins Pena. Este trecho mostra o juiz julgando um\n    caso de pessoas simples que moram na roça, no século XIX:\n\n Síntese para fixação\n • Recursos expressivos transformam usos cotidianos da língua.\n\n • gêneros literários organizam diferentes experiências.\n\n • a leitura considera tanto o texto quanto seu contexto."},{"area":"Linguagens","num":6,"title":"A vida em uma sociedade letrada","body":"Panorama do capítulo\n Leitura e escrita organizam práticas sociais e formas de participação.\n\n Conceitos essenciais\n • Gêneros textuais respondem a diferentes finalidades.\n\n • interpretar envolve reconhecer informações explícitas e implícitas.\n\n • práticas de letramento variam conforme contexto.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Para começar, imagine a seguinte situação: um nativo de uma tribo que vive em uma ilha da\n    Polinésia encontra-se, por algum motivo, em nosso país. Na sua tribo não há escrita, carros,\n    computadores... Você o vê parado, no meio da rua, e percebe que ele não sabe o que fazer para\n    atravessar sem ser pego pelos carros. Ele, provavelmente, não fala português. Como você faz para\n    ajudá-lo?\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    do dado 1, construímos um sentido que foi além da identificação dos elementos presentes (pistas de\n    estrada, números, símbolo da morte...). No caso do dado 2, não pudemos fazer nada além de nomear\n    o que estava representado: o número 100. Essas constatações nos levam a identificar o que faz do\n    dado 1 um texto:\n\n Texto-base 3 | página 6 do PDF do capítulo\n\n    Com essa informação histórica, o texto faz mais sentido, não é mesmo? O medo do homem\n    explica-se pela ameaça representada pelo Esquadrão da Morte. O desenho que aparece ao fundo é\n    do instrumento usado na geometria. O cartunista está fazendo um jogo de palavras com os sentidos\n    do termo “esquadrão”. Veja que, para compreender o cartum, precisamos recuperar o contexto\n    histórico a que ele se refere e saber o que significou o Esquadrão da Morte.\n\n Texto-base 4 | página 9 do PDF do capítulo\n\n    Persuadir: levar alguém a acreditar em algo que se diz e a agir de uma determinada maneira. É\n    usado, em alguns casos, como sinônimo de convencer, embora o convencimento diga respeito à\n    primeira parte da definição (levar alguém a acreditar em algo).\n\n Texto-base 5 | página 10 do PDF do capítulo\n\n    Um outro tipo de texto em que também percebemos a função narrativa (apresentação de uma série\n    de acontecimentos), sem que haja a construção de personagens, a caracterização de um cenário ou\n    o estabelecimento de um tempo é o relato.\n\n Texto-base 6 | página 12 do PDF do capítulo\n\n     Em lugar de apenas contar histórias, relatar acontecimentos importantes ou apresentar informações\n     sob a forma de notícias, em determinadas circunstâncias, temos a necessidade de usar a linguagem\n     de modo a convencer as pessoas com quem convivemos. Se temos um papel de liderança (em casa,\n     no serviço, na comunidade da qual fazemos parte), não podemos contar com a força para convencer\n     outras pessoas a agirem de uma certa forma ou fazerem o que julgamos mais acertado. Há ocasiões,\n     ainda, em que precisamos explicar algo, ensinar um\n\n Texto-base 7 | página 14 do PDF do capítulo\n\n     Sempre que precisarmos produzir um texto para orientar o comportamento de alguém, em uma\n     situação específica, devemos nos lembrar de que as instruções devem reproduzir exatamente as\n     ações a serem realizadas naquela situação.\n\n Texto-base 8 | página 16 do PDF do capítulo\n\n     É importante que, como o Sr. Wilson, saibamos defender nossos direitos, sempre que necessário. A\n     carta argumentativa é um texto que serve bem a essa finalidade. Como toda carta, ela é dirigida a\n     um interlocutor específico (no caso, a pessoa a quem devemos apresentar nossas queixas e\n     argumentos) e procura convencê-lo de que quem escreve tem razão em apresentar sua reclamação.\n\n Síntese para fixação\n • Gêneros textuais respondem a diferentes finalidades.\n\n • interpretar envolve reconhecer informações explícitas e implícitas.\n\n • práticas de letramento variam conforme contexto."},{"area":"Linguagens","num":7,"title":"Defendendo ideias e pontos de vista","body":"Panorama do capítulo\n Argumentar é sustentar uma posição por meio de razões e evidências.\n\n Conceitos essenciais\n • Tese e argumentos precisam estar relacionados.\n\n • exemplos e informações fortalecem justificativas.\n\n • conectivos ajudam a organizar relações entre ideias.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    – Você está falando da mulher daquele tal de Antônio? Ele trabalha comigo lá na fábrica e ontem\n    puxou prosa comigo no ônibus. Acho que ele é uma boa pessoa. Temos sorte de ter bons vizinhos,\n    você não acha?\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    Você verificou com suas análises que fotografar é um modo de manifestar opinião sobre as coisas e\n    as pessoas, pois encerra um ponto de vista sobre elas, isto é, um modo de vê-las. No entanto, não é\n    apenas fotografando que se pode fazer isso. Quando uma pessoa se comunica com a outra, falando\n    ou escrevendo, está também manifestando seus pontos de vista, suas opiniões sobre tudo e sobre\n    todos.\n\n Texto-base 3 | página 5 do PDF do capítulo\n\n    Quando os leitores “imaginados” pela revista ou jornal não aceitam as idéias de quem escreveu e,\n    portanto, não ficam convencidos, costumam reagir, muitas vezes até com indignação, escrevendo\n    críticas à seção de cartas das revistas e jornais, como veremos no trecho a seguir.\n\n Texto-base 4 | página 7 do PDF do capítulo\n\n    — Bem, a gente queria mesmo era olhar as vitrines... por isso fomos ao centro. Vi uma camisetinha\n    tão bonitinha numa loja... Sabe aquela de moda jovem que fica ao lado da sorveteria? É a minha\n    cara... e combina com minha calça nova...\n\n Texto-base 5 | página 8 do PDF do capítulo\n\n    O folheto, que veio dobrado ao meio, tinha esta frase na capa — Quero te conhecer melhor. — que\n    lembra uma frase muito usada quando alguém deseja conquistar outro alguém, quando quer\n    seduzi-lo, não é mesmo?\n\n Texto-base 6 | página 10 do PDF do capítulo\n\n    O país lucraria também ao poupar o dinheiro que é gasto para dar fim ao lixo. “Lixo é o único produto\n    da economia com preço negativo”, diz Sabetai. Em outras palavras, o processamento de lixo é o\n    único negócio no qual a aquisição da matéria-prima é remunerada – paga-se para livrar-se dela. E\n    paga-se muito. As prefeituras brasileiras costumam gastar entre 5% e 12% de seus orçamentos com\n\n    lixo.\n\n Texto-base 7 | página 12 do PDF do capítulo\n\n    Você sabe, por experiência própria, que nem sempre as pessoas concordam sobre as idéias, os\n    pontos de vista, as teses. Se concordassem, não haveria debates em que se discutem opiniões sobre\n    assuntos diversos, não é mesmo?\n\n Texto-base 8 | página 13 do PDF do capítulo\n\n    Texto 1 - LIMA, Barbosa. Entrevista concedida à revista Status. In VANOYE, Francis. Usos da\n    linguagem: problemas e técnicas da comunicação oral e escrita. São Paulo: Martins Fontes, 1987.\n    p.173.\n\n Síntese para fixação\n • Tese e argumentos precisam estar relacionados.\n\n • exemplos e informações fortalecem justificativas.\n\n • conectivos ajudam a organizar relações entre ideias."},{"area":"Linguagens","num":8,"title":"Das palavras ao contexto","body":"Panorama do capítulo\n O significado de enunciados depende de situações de comunicação.\n\n Conceitos essenciais\n • Uma palavra pode assumir diferentes sentidos.\n\n • escolhas linguísticas variam por interlocutor e objetivo.\n\n • compreender textos exige considerar referências e contexto.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    A segunda pessoa responde que a rua fica perto de onde supostamente os dois falantes se\n    encontram. Em seguida, começa a explicar o que é preciso fazer para chegar até lá.\n\n Texto-base 2 | página 3 do PDF do capítulo\n\n    A aparência externa do corpo humano, na sua opinião, estabelece a diferença (variedade) física entre\n    um ser e outro? Acreditamos que sim. Um ser é mais baixo, outro mais alto; um tem olhos grandes, o\n    outro, pequenos. Enfim, existem muitas variedades para infinitos corpos, contendo uma mesma\n    organização interna (todos têm coração, rim, sangue, veias etc., distribuídos de um mesmo modo).\n\n Texto-base 3 | página 4 do PDF do capítulo\n\n    O que acontece, porém, é que, na escola, encontra uma outra variedade da língua – a chamada culta\n    padrão – privilegiada e escolhida como modelo para várias situações de fala e escrita (por exemplo,\n    atividades científicas, literatura, documentos, meios de comunicação como jornais, revistas,\n    televisão).\n\n Texto-base 4 | página 6 do PDF do capítulo\n\n    No caso do trecho acima, ele faz parte de uma coletânea (conjunto) de textos chamada\n    “Linguagens”. Luis Fernando parece ter o objetivo de mostrar o pedantismo (a “chatice”, a\n    “grosseria”) de algumas linguagens e de algumas pessoas em determinados contextos.\n\n Texto-base 5 | página 8 do PDF do capítulo\n\n    Vocês teriam que usar uma variedade da língua portuguesa comum a ambos. Quer dizer, teriam que\n    escrever o fato (compra/venda do gado; valor da negociação/condições de pagamento) de uma forma\n    clara, possível de ser lida por ambos e por qualquer pessoa que pegasse esse texto. O ideal é que ele\n    fosse escrito em uma linguagem formal, padrão e, portanto, sem gírias, sem expressões coloquiais\n    ou regionais.\n\n Texto-base 6 | página 11 do PDF do capítulo\n\n    Você tem um carro com problemas. Com muito custo, leva-o até a retífica para ser consertado. No\n    final do dia, volta até lá e recebe um bilhete do mecânico, que já havia saído:\n\n Texto-base 7 | página 13 do PDF do capítulo\n\n    Acreditamos que sejam pouco instruídas, pela maneira como falam (“tu tá gozada”; “uns homão”,\n    “uns menino”) e pobres, por aquilo que falam: vão para a rua “bater coisas” para conseguirem\n    comida.\n\n Texto-base 8 | página 14 do PDF do capítulo\n\n    Assim, para além do que o autor nos diz, estão os nossos pressupostos; está a nossa capacidade de\n    olhar para o texto e ver o que nele está implícito; ou seja, as idéias que existem, mas que não são\n    ditas claramente.\n\n Síntese para fixação\n • Uma palavra pode assumir diferentes sentidos.\n\n • escolhas linguísticas variam por interlocutor e objetivo.\n\n • compreender textos exige considerar referências e contexto."},{"area":"Linguagens","num":9,"title":"Tecnologias de comunicação e informação: presença","body":"constante\n em nossas vidas\n\n Panorama do capítulo\n Meios tecnológicos transformam a circulação de mensagens e o acesso à informação.\n\n Conceitos essenciais\n • Cada mídia possui linguagem e alcance próprios.\n\n • novas ferramentas mudam hábitos de leitura e interação.\n\n • uso crítico exige avaliar autoria, intenção e confiabilidade.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    E a televisão? Com ela você recebe imagens e sons transmitidos de longe. Vê novelas, fica sabendo\n    de notícias do mundo inteiro, assiste a propagandas de produtos, à propaganda política ou a um jogo\n    de futebol.\n\n Texto-base 2 | página 3 do PDF do capítulo\n\n    todos os tipos. Sem esses meios de comunicação e de informação, teríamos de reinventar o nosso\n    modo de viver, nossa economia, ciência, educação, enfim, toda nossa sociedade.\n\n Texto-base 3 | página 5 do PDF do capítulo\n\n    Mas será que essas são as únicas possibilidades? E no caso de um livro em braile? No braile, a leitura\n    é feita passando-se o dedo sobre o texto, escrito por meio de pequenos pontos em relevo, o que\n    permite a leitura por pessoas com deficiência visual. Hoje em dia, é possível encontrar textos em\n    braile nos botões dos elevadores mais modernos, nos cardápios de algumas lanchonetes, além das\n    bibliotecas de livros em braile. Nesse caso, não se usa a visão nem a audição, mas sim o tato.\n    Também podemos apreciar uma escultura ou uma estátua através do nosso tato, fechando os olhos e\n    sentindo a escultura com as mãos.\n\n Texto-base 4 | página 7 do PDF do capítulo\n\n    Até aqui, você pôde classificar e compreender os meios de comunicação e informação de acordo com\n    a linguagem utilizada. Nós também podemos classificá-los por suas características materiais, físicas,\n    pelo tipo de tecnologia utilizada. Vamos dividir as tecnologias de comunicação e informação em três\n    áreas ou grupos principais: tecnologias gráficas, eletro-eletrônicas e da informática.\n\n Texto-base 5 | página 8 do PDF do capítulo\n\n    A técnica de impressão com tipos móveis, que acabamos de conhecer, chamada tipografia (escrita\n    com tipos), atualmente é apenas uma entre as diversas técnicas existentes, que não param de ser\n    criadas e desenvolvidas. As grandes impressoras industriais produzem milhares de páginas\n    impressas por minuto, com qualidade excepcional. A atual tecnologia criou impressoras para uso com\n\n    computadores que qualquer pessoa com pouco conhecimento pode usar em casa ou no escritório.\n\n Texto-base 6 | página 10 do PDF do capítulo\n\n    E, no caso dos rádios de comunicação, com os quais você pode falar e ouvir? Se você já usou ou viu\n    alguém usando um desses rádios de comunicação, deve ter percebido que não é possível falar e\n    ouvir ao mesmo tempo. Enquanto está transmitindo, o rádio não tem a capacidade de receber.\n\n Texto-base 7 | página 11 do PDF do capítulo\n\n    Primeiro, é preciso saber o que é e para que serve um computador. Computar quer dizer fazer\n    contas. Ele foi criado exatamente para isso, para solucionar problemas matemáticos. O computador,\n    em essência, é uma máquina eletrônica que faz cálculos, uma supercalculadora que só é capaz de\n    somar ou subtrair de 1 em 1. Essas máquinas, no entanto, são utilizadas em quase todos os ramos\n\n Texto-base 8 | página 13 do PDF do capítulo\n\n    A Web, junto com o e-mail, é responsável pela popularidade da Internet. Se a Internet já tem mais de\n    30 anos, a Web é bem mais recente, ainda não completou dez. Antes da Web, a Internet só utilizava\n    textos e, apesar de já ser importantíssima para as universidades e para os governos, era\n    desconhecida do público. Com a Web, tornou-se possível transmitir pela Internet documentos\n    contendo textos e imagens que são visualizados na tela do computador, além de sons. Cada\n    documento que você visualiza é uma página da Web. Outra característica é o uso do hipertexto. O\n    hipertexto é um documento que pode incluir ligações para outras partes desse ou para outros\n\n Síntese para fixação\n • Cada mídia possui linguagem e alcance próprios.\n\n • novas ferramentas mudam hábitos de leitura e interação.\n\n • uso crítico exige avaliar autoria, intenção e confiabilidade."},{"area":"Matemática","num":1,"title":"A Matemática: uma construção da humanidade","body":"Panorama do capítulo\n A Matemática se desenvolveu para resolver problemas práticos e criar formas de representação.\n\n Conceitos essenciais\n • Contagem, medida e comparação surgem em atividades humanas.\n\n • símbolos permitem generalizar relações.\n\n • modelos matemáticos ajudam a interpretar situações reais.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 3 do PDF do capítulo\n\n    O caçador poderia pensar de um modo semelhante, para resolver o problema, agrupando suas 22\n    aves em grupos de 2; agora, as pedrinhas seriam peixes: 3 para cada grupo de aves. Contanto as\n    pedrinhas, ele descobre que são 33 peixes!\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    Além de todos esses símbolos que utilizamos para nos comunicar e para resolver problemas, muitas\n    vezes nos valemos de uma “linguagem” , constituída de ícones, gráficos e diagramas,\n\n Texto-base 3 | página 7 do PDF do capítulo\n\n    Entretanto, os outros campos do conhecimento também têm solicitado respostas da Matemática para\n    solucionar seus problemas específicos, contribuindo indiretamente para seu desenvolvimento.\n\n Texto-base 4 | página 12 do PDF do capítulo\n\n    Para você desvendar uma construção estranha O quebra-cabeça a seguir é muito conhecido. Para\n    desvendá-lo, você precisa pensar na tangente de ângulos agudos em triângulos retângulos. Vamos\n    experimentar? A Figura 14 é uma região quadrada, montada com figuras de um quebra-cabeça\n    formado por 4 peças: dois triângulos e dois trapézios. Essas peças são compostas de outra maneira,\n    formando outra região retangular na Figura 15. Isso é possível, já que as peças que formam o\n    quebra-cabeça da Figura 14 são as mesmas que formam o quebra-cabeça da Figura 15. Concorda ou\n    não? Você acha que eles deveriam ter a mesma área, já que são compostos pelas mesmas peças?\n\n Texto-base 5 | página 14 do PDF do capítulo\n\n    eram soluções do problema. Entretanto considerou essas expressões inúteis, pois envolviam\n    números para os quais ainda não tinha sido dado nenhum significado: a raiz quadrada de número\n    negativo.\n\n Texto-base 6 | página 16 do PDF do capítulo\n\n    Já a questão do lixo é mais complexa, pois sua solução não depende apenas de você! Que tal uma\n    campanha de conscientização entre as pessoas que moram no seu quarteirão? Como fazer isso?\n    Seria bom fazer uma coleta seletiva? As pessoas sabem o que é isso?\n\n Texto-base 7 | página 19 do PDF do capítulo\n\n    Para que essa comunidade se conscientize da importância da redução – reutilização – reciclagem do\n    lixo, é importante que os resultados de sua pesquisa sejam mostrados e analisados por elas; nesse\n    caso, nada melhor do que um gráfico para que percebam clara e imediatamente em que situação se\n    encontram diante do problema e decidam que atitudes tomar para eliminá-lo.\n\n Texto-base 8 | página 22 do PDF do capítulo\n\n    Nestas poucas páginas, você teve a oportunidade de refletir sobre a Matemática como uma ciência\n    que foi e continua sendo construída pela humanidade, não só em decorrência de problemas que\n    surgem em muitas situações de nossa\n\n Síntese para fixação\n • Contagem, medida e comparação surgem em atividades humanas.\n\n • símbolos permitem generalizar relações.\n\n • modelos matemáticos ajudam a interpretar situações reais."},{"area":"Matemática","num":2,"title":"Lógica e argumentação: da prática à Matemática","body":"Panorama do capítulo\n Raciocinar matematicamente envolve identificar premissas, padrões e conclusões.\n\n Conceitos essenciais\n • Argumentos devem ser coerentes.\n\n • exemplos não bastam sempre para demonstrar uma regra geral.\n\n • dedução e estimativa auxiliam na solução de problemas.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Mas como convencer alguém, ou nós mesmos, de que determinada idéia é, de fato, correta? É\n    necessário que sejam apresentados fatos que justifiquem aquela idéia. Esses fatos são chamados de\n    argumentos. Eles devem ser bem claros, ter uma relação lógica entre si, de tal maneira que a idéia\n    considerada seja uma conseqüência natural dos argumentos apresentados.\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    Existem outros casos, porém, em que certo comportamento pode ser observado em muitos números\n    diferentes, o que nos dá vontade de dizer que ele ocorre com todos os números. Cuidado! Em\n    Matemática, analisar apenas alguns exemplos não é suficiente para comprovar uma propriedade,\n    pode no máximo nos dar uma “pista” de que aquela propriedade possa ser verdadeira.\n\n Texto-base 3 | página 7 do PDF do capítulo\n\n    No último mês, o consumo de energia elétrica na residência de Jorge, apontado na conta de luz, teve\n    um aumento significativo, subindo de 150 para 270 kWh. Como aparentemente não havia motivo\n    para tal aumento, Jorge começou a desconfiar que o problema pudesse ser da companhia\n    fornecedora de energia elétrica. Por isso, ele decidiu perguntar aos seus vizinhos se eles tinham tido\n    problema semelhante ultimamente. A Tabela 2 mostra o que cada vizinho respondeu:\n\n Texto-base 4 | página 8 do PDF do capítulo\n\n    • Júlio foi almoçar três sextas-feiras seguidas em um restaurante que foi inaugurado recentemente\n    perto de seu trabalho. Nas três vezes, acabou passando muito mal do estômago. Concluiu que a\n    comida do restaurante não lhe fazia bem e decidiu que não almoçaria mais naquele lugar.\n\n Texto-base 5 | página 11 do PDF do capítulo\n\n    Há 111 famílias que optaram pelo espaço para recreação. Destas, x também optaram pela sala de\n    leitura. Então, 111 - x são as que optaram apenas pelo espaço para recreação. Com o mesmo\n    raciocínio, concluímos que 183 - x optaram apenas pela sala de leitura. Como 24 não se interessaram\n    por nenhuma das duas obras, nosso diagrama fica:\n\n Texto-base 6 | página 13 do PDF do capítulo\n\n     Inverter uma relação de implicação é um erro bastante comum em argumentações, que não deve ser\n     feito. Existe, no entanto, uma maneira equivalente de escrevermos uma implicação, muito utilizada\n     em matemática, que iremos discutir a seguir.\n\n Texto-base 7 | página 16 do PDF do capítulo\n\n     Finalmente, pelo fato c concluímos que x + y + z = 180°. Acabamos de deduzir que a soma dos\n     ângulos internos de qualquer triângulo é sempre igual a 180°. Note que a nossa dedução é muito\n     parecida com a da menina do ursinho ou com aquela que usamos no dia-a-dia: partindo de alguns\n     fatos conhecidos e usando argumentos logicamente válidos, podemos produzir novas afirmações,\n     também verdadeiras. A única diferença é que na matemática sempre deixamos claros os fatos\n     iniciais que estamos utilizando, o que no cotidiano nem sempre fazemos.\n\n Texto-base 8 | página 20 do PDF do capítulo\n\n     Os números acima formam uma seqüência. Note que obedecemos uma ordem ao escrevermos esses\n     números. Dizemos que 2004 é o 1º termo da seqüência, 2008 é o 2º termo, 2012 é o 3º termo e,\n     assim, sucessivamente. Essa informação normalmente é dada de maneira mais resumida. Observe:\n\n Síntese para fixação\n • Argumentos devem ser coerentes.\n\n • exemplos não bastam sempre para demonstrar uma regra geral.\n\n • dedução e estimativa auxiliam na solução de problemas."},{"area":"Matemática","num":3,"title":"Convivendo com os números","body":"Panorama do capítulo\n Diferentes conjuntos numéricos descrevem quantidades e relações do cotidiano.\n\n Conceitos essenciais\n • Números podem representar contagens, medidas e variações.\n\n • operações exigem interpretar o contexto.\n\n • estimativas ajudam a verificar resultados.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Os algarismos: 0; 1; 2; 3; 4; 5; 6; 7; 8 e 9 escolhidos para compor o sistema de numeração decimal e\n    posicional foram por muito tempo denominados erroneamente algarismos arábicos, por terem sido\n    apresentados pelos árabes. Por volta do século VII, ao entrarem em contato com a cultura hindu e\n    motivados pela simplicidade e praticidade do sistema de numeração encontrado, tornaram-se seus\n    divulgadores em todo o Oriente.\n\n Texto-base 2 | página 3 do PDF do capítulo\n\n    Veja que, nos dois modos de solução, os números que usamos foram representados com vírgula.\n    Esses não são naturais nem inteiros. Podem ser chamados de racionais e também de números reais.\n    São conhecidos como decimais e podem ser escritos em forma de uma fração com denominador 10,\n    100, 1.000 etc.\n\n Texto-base 3 | página 8 do PDF do capítulo\n\n    Esse problema pode ser resolvido de várias maneiras. Uma delas seria usar o conceito de número\n    racional como o resultado da divisão de dois números inteiros. Observe como:\n\n Texto-base 4 | página 9 do PDF do capítulo\n\n    Às 9 horas da manhã, a temperatura estava agradável, fazia 18ºC. Ao meio dia, passou para 20°C e\n    às três horas da tarde, começou a esfriar caindo para 17°C. Durante a noite, esfriou muito e, às 2\n    horas da madrugada, os termômetros marcavam –2°C. Às 5 horas da manhã, já estava marcando –\n    4°C (C é a abreviação de Celsius e, ao lermos –2°C, devemos dizer dois graus Celsius negativos).\n    Encontre a maior variação de temperatura ocorrida nesse período.\n\n Texto-base 5 | página 12 do PDF do capítulo\n\n    Números inteiros também aparecem em gráficos. Gráficos são usados para transmitir dados e\n    informações. Observar e analisar esses dados e informações são habilidades necessárias a todas as\n    pessoas que queiram participar da sociedade complexa em que vivemos, pois os gráficos fazem\n    parte do cotidiano dessa sociedade.\n\n Texto-base 6 | página 14 do PDF do capítulo\n\n    O Brasil possui mais de 40 mil rios navegáveis, mas vinha utilizando muito pouco esse sistema, que é\n    80% mais econômico que o rodoviário. O Governo Federal, por meio do Ministério dos Transportes,\n    investiu muito nas hidrovias, e os resultados apareceram. A hidrovia do Tietê, por exemplo, passou a\n    movimentar 4 milhões de toneladas/ano, depois que ficou pronta a eclusa de Jupiá. E a circulação de\n    cargas no rio Madeira praticamente dobrou, passando de 1,3 milhões para 2,4 milhões de toneladas/\n    ano. Além de mais econômico, o transporte hidroviário é o que menos interfere na natureza,\n    deixando preservados os nossos rios, patrimônio de muitos brasileiros. Com os investimentos do\n    Governo Federal, o Brasil está redescobrindo as hidrovias e mudando o seu sistema de transportes. E\n    os transportes estão ajudando a mudar o Brasil (....).\n\n Texto-base 7 | página 16 do PDF do capítulo\n\n    De acordo com o gráfico da Figura 12, podemos afirmar que: a) a maior variação do PIB da\n    agropecuária foi de 3,23. b) a maior variação do PIB da agropecuária foi de 3,48. c) a diferença entre\n    o menor valor do PIB da agropecuária e o valor registrado no 1º trimestre de 2002 foi de 3,23. d) o\n    maior valor do PIB da agricultura foi de 1,85.\n\n Texto-base 8 | página 17 do PDF do capítulo\n\n    Os mutirões entre vizinhos, para a construção da casa própria, ocorrem em grande número em\n    diferentes regiões do país. Veja uma possibilidade de usar seu conhecimento dos números para\n    resolver problemas que podem aparecer em construções.\n\n Síntese para fixação\n • Números podem representar contagens, medidas e variações.\n\n • operações exigem interpretar o contexto.\n\n • estimativas ajudam a verificar resultados."},{"area":"Matemática","num":4,"title":"Nossa realidade e as formas que nos rodeiam","body":"Panorama do capítulo\n Geometria descreve formas, posições e relações espaciais.\n\n Conceitos essenciais\n • Figuras planas e espaciais aparecem em objetos e construções.\n\n • propriedades geométricas ajudam a medir e projetar.\n\n • representações permitem comparar formas.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 3 do PDF do capítulo\n\n    De fato, ao longo da história da Humanidade, foram surgindo, no dia-a-dia dos diversos povos,\n    problemas que eles tiveram que solucionar. As soluções encontradas foram sendo passadas de pai\n    para filho, formando essa “sabedoria” que todos nós possuímos. Alguns escritos que ficaram dos\n    povos antigos, muitas vezes, descrevem alguma situação e a solução encontrada, justificando\n    apenas que “fazendo assim, dá certo”.\n\n Texto-base 2 | página 6 do PDF do capítulo\n\n    Um bom argumento para justificar essa escolha pode ser verificado por você. Pegue duas\n    embalagens de produtos quaisquer, uma com a 1ª forma apresentada e outra com a 2ª forma, sem\n    uma das tampas. Você deve construir uma tampa para cada embalagem, apoiando-a sobre um papel\n    grosso, desenhando o contorno da parte a ser tampada e depois recortando-o. Agora, tente guardar\n    cada tampa dentro da sua respectiva caixa, sem dobrá-la nem amassá-la. Você deve ter notado que\n    apenas a tampa da 1ª embalagem pode ser guardada nas condições do problema, isto é, sem ser\n    dobrada nem amassada. Isso quer dizer que se o poço ou as panelas tivessem a 1ª forma haveria o\n    risco de se deixar a tampa cair no fundo!\n\n Texto-base 3 | página 10 do PDF do capítulo\n\n    Vamos imaginar que a rua tem 8 metros de largura. Então, o pedestre poderá fazer a travessia\n    perpendicularmente às calçadas, ou atravessar a rua seguindo uma direção oblíqua.\n\n Texto-base 4 | página 14 do PDF do capítulo\n\n    Os antigos gregos também descobriram essa propriedade que você acabou de verificar. Eles\n    provaram que essa propriedade vale para qualquer triângulo e criaram o “teorema da soma dos\n    ângulos internos de um triângulo”:\n\n Texto-base 5 | página 16 do PDF do capítulo\n\n    Como vimos até aqui, nossos ladrilhos têm formas poligonais; e os polígonos possuem “muitos\n    ângulos”. Estes ângulos têm um papel importante, quando se pensa em ladrilhamentos. Você viu\n    que, conforme as aberturas dos lados dos ladrilhos (os ângulos dos polígonos), eles servem ou não\n    para recobrir uma superfície sem deixar vãos ou se sobreporem.\n\n Texto-base 6 | página 21 do PDF do capítulo\n\n    Esse gráfico, constituído por uma poligonal das freqüências, nos indica as variações da grandeza\n    considerada por meio das alturas atingidas pelos extremos dos segmentos de reta que formam essa\n    linha poligonal.\n\n Texto-base 7 | página 23 do PDF do capítulo\n\n    É possível que, entre outras coisas, você tenha se lembrado de ter visto fotos ou ilustrações das\n    famosas pirâmides do Egito, construídas há cerca de 5000 anos. Elas são pirâmides como essa da\n    figura.\n\n Texto-base 8 | página 26 do PDF do capítulo\n\n    Analisou, também, alguns problemas que os homens foram tendo que resolver para facilitar seu\n    modo de vida e como as soluções para eles podem ser encontradas com maior facilidade, quando se\n    tem conhecimentos matemáticos.\n\n Síntese para fixação\n • Figuras planas e espaciais aparecem em objetos e construções.\n\n • propriedades geométricas ajudam a medir e projetar.\n\n • representações permitem comparar formas."},{"area":"Matemática","num":5,"title":"Medidas e seus usos","body":"Panorama do capítulo\n Medir significa comparar grandezas com unidades estabelecidas.\n\n Conceitos essenciais\n • Unidades precisam ser adequadas ao problema.\n\n • conversões preservam o significado das quantidades.\n\n • precisão e estimativa dependem da situação.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    As unidades de medidas utilizadas para se estabelecer um padrão de comparação foram até certa\n    época definidas arbitrariamente. Até o final do século XVIII, todos os sistemas de medidas existentes\n    eram baseados nos costumes e nas tradições. Algumas partes do corpo humano – a palma da mão, o\n    polegar, o braço ou a passada – e alguns utensílios de uso cotidiano, tais como cuias e vasilhas,\n    foram os primeiros padrões de comparação usados para medir. Com o tempo, cada civilização definiu\n    padrões diferentes e fixou suas próprias unidades de medidas.\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    A necessidade de medidas cada vez mais precisas surge a partir do Renascimento, com as grandes\n    navegações e o desenvolvimento da ciência experimental. Para os cientistas da era moderna,\n    conhecer um fenômeno significa compreendê-lo e poder medi-lo. Nos séculos XVII e XVIII,\n    multiplicam-se os instrumentos de precisão, como termômetros, relógios e lunetas. Com a revolução\n    industrial e o desenvolvimento do capitalismo, o comércio internacional também se intensifica e\n\n Texto-base 3 | página 5 do PDF do capítulo\n\n    b) Você já pensou no calor produzido pela explosão de uma bomba atômica? Sabendo que a\n    temperatura média da chama do fogão é 1.100K e que a temperatura gerada por uma bomba\n    atômica é 300.000K, estabeleça uma comparação entre essas temperaturas usando como padrão a\n    temperatura média da chama do fogão. (Resposta ao final da página)\n\n Texto-base 4 | página 7 do PDF do capítulo\n\n    Dizer que a velocidade da luz é 300.000 km/s é equivalente a dizer que a luz percorre 300.000\n    quilômetros em um intervalo de tempo igual a 1 segundo. Para saber quanto a luz percorre em um\n    ano, precisamos inicialmente converter 1 ano em segundos e, depois, 300.000 km em metros:\n\n Texto-base 5 | página 10 do PDF do capítulo\n\n    A Figura 7 mostra a embalagem de uma determinada marca de refrigerante de baixo teor calórico.\n    Admitindo uma informação do rótulo de que 2 litros do refrigerante contêm 9kcal, o valor calórico de\n    uma porção de 200ml, indicado na embalagem como sendo de 0kcal, deve ser corrigido para: a)\n    0,20kcal. b) 0,45kcal. c) 0,60kcal. d) 0,90kcal.\n\n Texto-base 6 | página 13 do PDF do capítulo\n\n    Para respondermos a esta pergunta, basta dividirmos 6 cm por 3 cm. Segue que neste arco cabem 2\n    raios. Podemos dizer que o ângulo Â mede 2 radianos (abrevia-se 2 rad). Em geral, uma fórmula\n    bastante simples que nos ajuda a encontrar um ângulo Â em radianos, a partir de um arco de\n    comprimento igual a C em um círculo de raio R, é:\n\n Texto-base 7 | página 15 do PDF do capítulo\n\n    11) A ponta de um limpador de pára-brisa de 45 cm de comprimento percorreu um arco de 1 radiano.\n    Calcule a distância percorrida pela ponta do limpador e, em seguida, calcule um valor aproximado\n    em graus para o ângulo percorrido pela ponta do limpador.\n\n Texto-base 8 | página 20 do PDF do capítulo\n\n    Ao observarmos a planta da casa (Figura 16), podemos estar interessados em comparar o tamanho\n    de alguns cômodos, ou seja, em comparar a área total desses cômodos. No problema que se segue\n    iremos calcular a área de dois banheiros e de um lavabo para verificarmos qual deles é maior: 12)\n    Comparando o lavabo, o banheiro 1 e o banheiro 2, qual deles é maior?\n\n Síntese para fixação\n • Unidades precisam ser adequadas ao problema.\n\n • conversões preservam o significado das quantidades.\n\n • precisão e estimativa dependem da situação."},{"area":"Matemática","num":6,"title":"As grandezas no dia a dia","body":"Panorama do capítulo\n Grandezas podem variar conjuntamente e apresentar relações de proporcionalidade.\n\n Conceitos essenciais\n • Razões comparam quantidades.\n\n • tabelas e expressões representam variações.\n\n • distinguir relações proporcionais de não proporcionais evita erros.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Saber resolver problemas faz com que adquiramos mais confiança em nós e sejamos mais\n    respeitados pelos colegas que nos vêem como alguém que contribui com idéias. A Matemática pode\n    dar uma grande contribuição para isso, à medida que explora a resolução de problemas e a\n    construção de estratégias e favorece o desenvolvimento da capacidade de investigar, argumentar,\n    comprovar e justificar.\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    Como você pôde perceber, em algumas situações é possível comparar a variação das grandezas,\n    fazer os cálculos necessários e prever os resultados, mas em outras isso não é possível.\n\n Texto-base 3 | página 11 do PDF do capítulo\n\n    Um clube decidiu promover uma competição de atletismo entre seus atletas. E, querendo incentivar\n    e motivar os atletas participantes, ofereceu um prêmio de R$ 600,00 a ser dividido entre aqueles que\n    fizerem os 100 metros rasos em menos de 13 segundos. Se 2 atletas conseguirem fazer isso, cada\n    um receberá R$ 300,00. E se 4 atletas conseguirem, quanto receberá cada um ?\n\n Texto-base 4 | página 15 do PDF do capítulo\n\n    Você sabia que a vazão de uma torneira é diretamente proporcional ao tempo em que ela fica\n    aberta? Por exemplo, se você escovar os dentes em 5 minutos deixando a torneira aberta, estará\n    gastando 12 litros de água por dia, quantidade que uma pessoa poderia beber durante 6 dias. No\n    entanto, se escovar os dentes de maneira econômica, ou seja, mantendo a torneira fechada e só\n    usando água quando for necessário, gastará, em média, 1 litro. A economia será de\n    aproximadamente 11 litros de água por dia. Pense nisso sempre que for escovar os dentes, fazer a\n    barba etc.\n\n Texto-base 5 | página 18 do PDF do capítulo\n\n    É bastante freqüente entre os brasileiros o hábito de tomar medicamentos por conta própria, por\n    sugestão de amigos ou pessoas não habilitadas a receitar. Na área de saúde, esse procedimento\n    chama-se automedicação – que quer dizer “medicar a si mesmo”.\n\n Texto-base 6 | página 20 do PDF do capítulo\n\n    Aproveite os dados do problema acima e responda à seguinte questão: Se a revendedora tivesse\n    aplicado um desconto de 5,5% sobre o valor inicial do automóvel, poderíamos afirmar que: a) o valor\n    do desconto seria de R$ 500,00. b) o valor do automóvel após esse desconto seria de R$ 7.150,50. c)\n    a porcentagem que representa o valor do automóvel após o desconto seria de 95,5%. d) o valor\n    desse desconto seria superior a R$ 400,00.\n\n Texto-base 7 | página 24 do PDF do capítulo\n\n    1) Uma loja de informática está vendendo um computador por R$ 2500,00 à vista, ou em 2 parcelas:\n    R$ 1.500,00 de entrada e R$ 1.500,00 ao fim de 30 dias. O preço desse computador à vista é\n    diferente do preço a prazo, porque estão sendo cobrados juros pelo parcelamento da dívida. Qual\n    será o valor do juro mensal que essa loja está cobrando pelo parcelamento?\n\n Texto-base 8 | página 26 do PDF do capítulo\n\n    Dona Vera possui uma televisão muito antiga de 14 polegadas, por isso há algum tempo vem\n    juntando uma certa quantia em dinheiro para comprar uma televisão maior e mais moderna. Quando\n    viu a oferta de uma televisão de 20 polegadas em 10 vezes de R$ 62,20 (Figura 12), não pensou em\n    aguardar um pouco mais para comprar uma televisão com uma tela maior (Figura 13) e nem sequer\n    fez os cálculos para verificar quanto estava pagando de juros.\n\n Síntese para fixação\n • Razões comparam quantidades.\n\n • tabelas e expressões representam variações.\n\n • distinguir relações proporcionais de não proporcionais evita erros."},{"area":"Matemática","num":7,"title":"A Matemática por trás dos fatos","body":"Panorama do capítulo\n Modelos e expressões matemáticas ajudam a interpretar situações sociais e científicas.\n\n Conceitos essenciais\n • Variáveis representam quantidades desconhecidas ou mutáveis.\n\n • relações podem ser descritas por fórmulas.\n\n • é preciso interpretar resultados à luz do contexto.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 3 do PDF do capítulo\n\n    Caso um cliente desejasse comprar 17 pãezinhos, seria necessário calcular o preço, pois ele não\n    consta da tabela. É possível que nessa hora sejam trocadas as seguintes palavras entre o caixa e o\n    cliente:\n\n Texto-base 2 | página 7 do PDF do capítulo\n\n    O sistema de identificar regiões que estamos usando é útil quando queremos encontrar uma rua ou\n    uma praça num mapa, pois conduz nosso olhar para uma pequena região do mapa e nessa região\n    encontramos o local procurado.\n\n Texto-base 3 | página 11 do PDF do capítulo\n\n    do ponto de vista matemático substituir um pelo outro. Às vezes eles são tão equivalentes que a\n    escolha entre usar o gráfico, a tabela ou a lei matemática é definida apenas por nossa preferência\n    pessoal.\n\n Texto-base 4 | página 12 do PDF do capítulo\n\n    De posse do modelo matemático P(t) = 0,02t (Foi esse mesmo que você encontrou?), você pode\n    calcular o custo da energia consumida por uma lâmpada acesa por 5 horas. Se a lâmpada ficar acesa\n    5 horas por dia, qual seu custo mensal? (Admita que um mês tem 30 dias).\n\n Texto-base 5 | página 14 do PDF do capítulo\n\n    Com a lei matemática você poderá responder a outras questões que não seriam tão facilmente\n    respondidas com os procedimentos usados no início do problema. Use a lei obtida para respondê-las:\n\n Texto-base 6 | página 15 do PDF do capítulo\n\n    A necessidade de reduzir custos e otimizar cada detalhe da cadeia produtiva fez com que surgisse na\n    indústria automobilística japonesa o conceito de “Produção Enxuta”, que conferiu grande\n    competitividade à produção industrial do Japão e levou a indústria ocidental a rever seus princípios\n    para fazer frente aos poderosos concorrentes.\n\n Texto-base 7 | página 17 do PDF do capítulo\n\n     Vamos fazer uma leitura atenta dessas notícias. a) Olhando o gráfico, verifique qual era a população\n     da cidade quando o estudo começou. O gráfico também nos traz a informação de que, três anos\n     depois, a população passou a 13.925 habitantes. Qual foi o aumento da população nesses 3 anos? b)\n     Calcule também o aumento da população em um ano, admitindo que seja igual nos três anos. c) Com\n     esses dados você pode obter o modelo matemático desse crescimento. Faça isso! d) No jornal foi dito\n     que o estudo foi iniciado em 1996, assim x=0 corresponde a 1996. Qual o valor de x para 2015? e)\n     Qual deverá ser a população de Sapiência em 2015? f) Após analisar os dados obtidos com seus\n     cálculos, escreva uma pequena carta para o redator do Jornal de Sapiência com um comentário sobre\n     a credibilidade da notícia sobre a estação de tratamento de esgotos.\n\n Texto-base 8 | página 19 do PDF do capítulo\n\n     c)Para saber o que esse número representa, considere que uma família pode viver com conforto\n     consumindo 0,3 MWh por mês. Verifique quanto tempo essa família levaria para consumir a\n     quantidade de energia economizada por esse aumento de 1% na reciclagem.\n\n Síntese para fixação\n • Variáveis representam quantidades desconhecidas ou mutáveis.\n\n • relações podem ser descritas por fórmulas.\n\n • é preciso interpretar resultados à luz do contexto."},{"area":"Matemática","num":8,"title":"Gráficos e tabelas do dia a dia","body":"Panorama do capítulo\n Representações gráficas organizam informações e permitem comparações.\n\n Conceitos essenciais\n • Eixos, escalas e legendas precisam ser lidos com atenção.\n\n • gráficos diferentes enfatizam aspectos distintos.\n\n • tendências não equivalem necessariamente a causas.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    Os gráficos e tabelas são um desses meios, se destacando das demais formas de comunicação, pela\n    possibilidade de transmitir um grande volume de informações de modo sintético e de fácil\n    interpretação.\n\n Texto-base 2 | página 3 do PDF do capítulo\n\n    Uma grande vantagem do uso de tabelas é a possibilidade de trabalhar com várias informações\n    simultâneas; por exemplo, poderíamos aproveitar a mesma tabela para acrescentar novas\n    informações, como o preço da plastificação de documentos.\n\n Texto-base 3 | página 6 do PDF do capítulo\n\n    • Suponha que você tenha perdido seu cachorro de estimação e gostaria de colocar cartazes com a\n    foto dele e um telefone de contato. Você se dispôs a gastar R$ 10,00 para tirar cópia desses cartazes.\n    Quantas cópias você poderá tirar?\n\n Texto-base 4 | página 8 do PDF do capítulo\n\n    Observe agora só o eixo do tempo. Veja que não estão assinalados todos os minutos de 0 a 20.\n    Assinale você os que faltam. O mesmo ocorre nos valores da velocidade que se encontram no eixo\n    vertical. Estes valores estão marcados de dez em dez. Assinale no eixo um ponto que corresponda a\n    uma velocidade de 65 km/h. Você deve ter assinalado no meio do segmento de reta entre 60 e 70.\n    Do mesmo modo, poderíamos utilizar nossa estimativa para marcar um ponto correspondente à\n    velocidade de 31 km/h. Onde você marcaria?\n\n Texto-base 5 | página 10 do PDF do capítulo\n\n    A taxa de natalidade indica quantas crianças nasceram durante um ano em uma determinada região,\n    em relação à população total dessa mesma região. Por exemplo, podemos ver pela tabela abaixo que\n    a região Nordeste tem uma taxa de natalidade de 24 %. Isso quer dizer que, num grupo de 100\n    pessoas adultas, nascem 24 crianças a cada ano.\n\n Texto-base 6 | página 12 do PDF do capítulo\n\n    O Gráfico 4 apresenta os hábitos de consumo de água de alguns lugares. Este gráfico, chamado de\n    gráfico de barras, possui uma legenda à direita, que relaciona a informação aliada a uma cor com as\n\n    barras do gráfico.\n\n Texto-base 7 | página 15 do PDF do capítulo\n\n    custa hoje R$ 2,00, com uma inflação de 1.000% a.a., depois de um ano estaria custando R$ 20,00.\n    Depois de mais um ano, estaria custando R$ 200,00, chegando ao absurdo de custar R$ 2.000,00,\n    após mais um ano. Parece loucura, mas já foi assim.\n\n Texto-base 8 | página 17 do PDF do capítulo\n\n    A curva que aparece próxima a esses pontos indica os pesos normais que uma criança deve\n    apresentar durante os 24 primeiros meses de vida. Os médicos costumam fazer comparações entre\n    os pontos marcados e essa curva.\n\n Síntese para fixação\n • Eixos, escalas e legendas precisam ser lidos com atenção.\n\n • gráficos diferentes enfatizam aspectos distintos.\n\n • tendências não equivalem necessariamente a causas."},{"area":"Matemática","num":9,"title":"Uma conversa sobre fatos do nosso dia a dia","body":"Panorama do capítulo\n A análise de dados e do acaso ajuda a lidar com incertezas.\n\n Conceitos essenciais\n • Frequências resumem ocorrências.\n\n • probabilidades descrevem chances em situações definidas.\n\n • conclusões estatísticas exigem atenção aos dados disponíveis.\n\n Trechos do livro original — leitura contextualizada\n\nTexto-base 1 | página 2 do PDF do capítulo\n\n    No decorrer de nossa conversa, iremos propor a você que reflita sobre algumas questões do dia-a-\n    dia e que as tente responder, para perceber a teoria envolvida. Você irá adquirir conhecimentos,\n    interpretando informações, que lhe darão oportunidade de compreender fenômenos naturais e\n    sociais.\n\n Texto-base 2 | página 4 do PDF do capítulo\n\n    Vamos imaginar que sua cidade tenha 24.000 habitantes, com mais de 16 anos, e que esteja\n    organizada em 80 bairros. Você poderá sortear 10% dos bairros e 10% dos 24.000 habitantes, com\n    mais de 16 anos, ou seja, 8 bairros e 2.400 habitantes distribuídos nestes 8 bairros.\n\n Texto-base 3 | página 6 do PDF do capítulo\n\n    É comum, também, dias antes das eleições, serem feitas pesquisas sobre a preferência dos eleitores\n    por determinados candidatos, sendo feitas previsões de quem poderá ser o vencedor. Essa pesquisa\n    é feita com uma parte dos eleitores.\n\n Texto-base 4 | página 7 do PDF do capítulo\n\n    Lembre-se, a representatividade da amostra é importante para que o resultado obtido possa ser\n    estendido para a população. Quanto maior a porcentagem de elementos da amostra, maior será a\n    representatividade.\n\n Texto-base 5 | página 10 do PDF do capítulo\n\n    O texto indica que há 317.787 casos de dengue. No total, podemos dizer que esses casos são,\n    aproximadamente, 318 mil, sendo 41% no Estado do Rio de Janeiro. Quantos são os casos nesse\n    Estado?\n\n Texto-base 6 | página 11 do PDF do capítulo\n\n    Você viu como fatos complexos podem, muitas vezes, ser representados por gráficos e descritos\n    numericamente, facilitando sua compreensão. A sociedade moderna acumula uma grande\n    quantidade de informações e dados numéricos relativos a eventos de toda ordem: econômicos,\n    esportivos, históricos, geográficos, políticos ou da natureza.\n\n Texto-base 7 | página 17 do PDF do capítulo\n\n    Como a lei determinou que todos os consumidores de São Paulo, a partir de 4 de junho, deveriam\n    economizar 20% no consumo de energia elétrica, que porcentagem dona Luz poderia gastar? A\n    Eletropaulo calculou 80% de 410kwh:\n\n Texto-base 8 | página 20 do PDF do capítulo\n\n    Você deve ter percebido que, nesse caso, a média (160cm) e a mediana (155cm) são valores\n    diferentes. Na maioria dos casos isso acontece porque essas medidas têm significados diferentes.\n\n Síntese para fixação\n • Frequências resumem ocorrências.\n\n • probabilidades descrevem chances em situações definidas.\n\n • conclusões estatísticas exigem atenção aos dados disponíveis."}];const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const map={'Leitura - Humanas':'Humanas','Leitura - Natureza':'Natureza','Leitura - Linguagens':'Linguagens','Leitura - Matemática':'Matemática'};const old=render;render=function(){old();const area=map[tab];if(!area)return;const a=lessons.filter(l=>l.area===area);let root=document.querySelector('#app');let done={};try{done=JSON.parse(localStorage.getItem('enem-encceja-aulas-v1')||'{}')||{}}catch(e){}const finished=a.filter(l=>!!done[l.area+'-'+l.num]).length;root.insertAdjacentHTML('beforeend','<section class="panel"><h2>📚 Aulas do ENCCEJA — '+esc(area)+'</h2><p><strong>'+finished+' de '+a.length+' aulas concluídas</strong> · '+(a.length-finished)+' pendentes</p><p>9 aulas teóricas baseadas no material MEC/Inep (2006), aprofundadas para o ENEM. Exercícios ficam nos Shorts.</p><div class="enem-section-list">'+a.map(l=>{const ok=!!done[l.area+'-'+l.num];return '<button class="enem-section" onclick="enemOpenLesson(\''+l.area+'\','+l.num+')" aria-label="Aula '+l.num+', '+(ok?'concluída':'pendente')+'"><span>'+(ok?'✅':'📘')+'</span><span><strong>Aula '+l.num+(ok?' · Concluída':'')+'</strong><small>'+esc(l.title)+'</small></span><span>'+(ok?'✓':'›')+'</span></button>'}).join('')+'</div></section>')};window.enemOpenLesson=function(area,num){const l=lessons.find(x=>x.area===area&&x.num===num);if(!l)return;const html='<section class="panel"><button onclick="go(\'Leitura - '+area+'\')">← Voltar às aulas</button><h2>Aula '+num+' — '+esc(l.title)+'</h2><p class="muted">Base teórica ENCCEJA MEC/Inep (2006) · complemento ENEM</p><div style="white-space:pre-wrap;line-height:1.7">'+esc(l.body)+'</div><button class="primary" onclick="enemCompleteLesson(\''+area+'\','+num+')">✓ Concluir aula</button><p id="enemLessonFeedback"></p></section>';document.querySelector('#app').innerHTML=html;window.scrollTo?.(0,0)};window.enemCompleteLesson=function(area,num){const key='enem-encceja-aulas-v1',done=JSON.parse(localStorage.getItem(key)||'{}');const id=area+'-'+num;if(!done[id]){done[id]=new Date().toISOString();localStorage.setItem(key,JSON.stringify(done));window.dispatchEvent(new CustomEvent('enem-energia',{detail:{tipo:'leitura'}}))}document.getElementById('enemLessonFeedback').textContent='✓ Aula concluída e progresso salvo.'};window.enemEnccejaLessons=lessons;})();